```typescript
import { mapUserGrade } from "./sm2";

async function main(): Promise<void> {
  // 1. Load cards (NOTE: loadCards is currently a stub — see prerequisites in overview.md)
  const cards = loadCards(cardsFilePath);

  // 2. Load review states
  const reviewsPath = getDefaultReviewsPath(cardsFilePath);
  const reviewStates = await loadReviewStates(reviewsPath);

  // 3. Capture session time ONCE to avoid clock drift / midnight boundary issues
  const now = new Date();

  // 4. Build due queue
  const dueCards = getDueCards(cards, reviewStates, now);

  if (dueCards.length === 0) {
    console.log("No cards due for review. Come back later!");
    return;
  }

  // 5. Start quiz session
  const session = startQuiz(dueCards);

  // 6. Quiz loop: for each card, show front, reveal back, prompt grade
  //    Save after EACH card to prevent data loss on interruption.
  while (!isQuizComplete(session)) {
    const card = currentCard(session);
    if (!card) break;
    // ... show card front, wait for reveal, show back ...
    // ... prompt: [1] Again  [2] Good  [3] Easy ...
    const userInput = promptUserGrade(); // returns 1 | 2 | 3
    const grade = mapUserGrade(userInput); // maps to Grade 1 | 4 | 5
    gradeCard(session, grade, reviewStates, now);

    // Save incrementally after each card to guard against session interruption
    const mergedStates = new Map([...reviewStates, ...session.updatedStates]);
    await saveReviewStates(reviewsPath, mergedStates);
  }

  // 7. Final merge and save (ensures consistency even if loop logic changes)
  const mergedStates = new Map([...reviewStates, ...session.updatedStates]);
  await saveReviewStates(reviewsPath, mergedStates);

  // 8. Show summary
  const summary = calculateReviewSummary(
    session.grades,
    reviewStates,
    mergedStates,
    now,
  );
  console.log(formatReviewSummary(summary));
}
```

**Key points**:
- `const now = new Date()` is captured once at session start and threaded through all calls. This prevents clock drift and midnight-boundary inconsistencies.
- Grade mapping (user input 1/2/3 to SM-2 Grade 1/4/5) uses `mapUserGrade()` from `sm2.ts`.
- Review states are saved after each card to prevent data loss on session interruption (Ctrl+C, crash, etc.).
- Review states are merged (spread existing, overwrite with updated) before saving.

