export function getDueCards(cards: readonly Card[], reviewStates: ReadonlyMap<string, ReviewState>, now: Date, config?: Partial<ScheduleConfig>): Card[] {
  return []; // stub
}

/** Count cards due by end of tomorrow (inclusive of already-overdue cards). */
export function countDueTomorrow(reviewStates: ReadonlyMap<string, ReviewState>, now: Date): number {
  return 0; // stub
}
```

