input.new_string:
/** Calculate next review state using SM-2 algorithm. */
export function calculateNextReview(
	current: ReviewState,
	grade: Grade,
	now: Date,
): ReviewState {
	const oldEF = current.easeFactor;
	const newEF = Math.max(
		MIN_EASE_FACTOR,
		oldEF + (0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02)),
	);

	let interval: number;
	let repetition: number;

	if (grade < 3) {
		// Again: reset
		repetition = 0;
		interval = 1;
	} else {
		if (current.repetition === 0) {
			interval = 1;
		} else if (current.repetition === 1) {
			interval = 6;
		} else {
			interval = Math.max(1, Math.round(current.interval * newEF));
		}
		repetition = current.repetition + 1;
	}

	const nextReviewDate = new Date(
		now.getTime() + interval * 24 * 60 * 60 * 1000,
	).toISOString();

	return {
		cardId: current.cardId,
		repetition,
		easeFactor: newEF,
		interval,
		nextReviewDate,
	};
}

