input.new_string:
/** Get cards that are due for review, including new cards up to session limit. */
export function getDueCards(
	cards: readonly Card[],
	reviewStates: ReadonlyMap<string, ReviewState>,
	now: Date,
	config?: Partial<ScheduleConfig>,
): Card[] {
	const maxNew = config?.maxNewCardsPerSession ?? DEFAULT_MAX_NEW_CARDS_PER_SESSION;
	const dueCards: Card[] = [];
	const newCards: Card[] = [];

	for (const card of cards) {
		const state = reviewStates.get(card.id);
		if (!state) {
			newCards.push(card);
		} else if (isDue(state, now)) {
			dueCards.push(card);
		}
	}

	dueCards.sort((a, b) => {
		const stateA = reviewStates.get(a.id) as ReviewState;
		const stateB = reviewStates.get(b.id) as ReviewState;
		return (
			new Date(stateA.nextReviewDate).getTime() -
			new Date(stateB.nextReviewDate).getTime()
		);
	});

	return [...dueCards, ...newCards.slice(0, maxNew)];
}

