/** Count cards due by end of tomorrow (inclusive of already-overdue cards). */
export function countDueTomorrow(
	reviewStates: ReadonlyMap<string, ReviewState>,
	now: Date,
): number {
	const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
	let count = 0;
	for (const state of reviewStates.values()) {
		if (new Date(state.nextReviewDate).getTime() <= tomorrow.getTime()) {
			count++;
		}
	}
	return count;
}

