import { describe, expect, it } from "bun:test";
import type { Card } from "../src/card";
import {
	DEFAULT_EASE_FACTOR,
	DEFAULT_MAX_NEW_CARDS_PER_SESSION,
	MIN_EASE_FACTOR,
	type ReviewState,
	calculateNextReview,
	countDueTomorrow,
	createInitialReviewState,
	getDueCards,
	isDue,
	mapUserGrade,
} from "../src/sm2";

const NOW = new Date("2026-04-04T12:00:00Z");

function makeState(overrides: Partial<ReviewState> & { cardId: string }): ReviewState {
	return {
		repetition: 0,
		easeFactor: DEFAULT_EASE_FACTOR,
		interval: 0,
		nextReviewDate: NOW.toISOString(),
		...overrides,
	};
}

function makeCard(id: string): Card {
	return { id, front: "Q", back: "A", tags: [], createdAt: NOW.toISOString() };
}

describe("mapUserGrade", () => {
	it("maps 1 → 1", () => expect(mapUserGrade(1)).toBe(1));
	it("maps 2 → 4", () => expect(mapUserGrade(2)).toBe(4));
	it("maps 3 → 5", () => expect(mapUserGrade(3)).toBe(5));
});

describe("createInitialReviewState", () => {
	it("returns correct defaults", () => {
		const state = createInitialReviewState("card-1", NOW);
		expect(state.cardId).toBe("card-1");
		expect(state.repetition).toBe(0);
		expect(state.easeFactor).toBe(DEFAULT_EASE_FACTOR);
		expect(state.interval).toBe(0);
		expect(state.nextReviewDate).toBe(NOW.toISOString());
	});
});

describe("calculateNextReview", () => {
	it("Grade 1 (Again): resets rep to 0, interval to 1, EF decreases", () => {
		const current = makeState({ cardId: "c1", repetition: 1, interval: 6 });
		const result = calculateNextReview(current, 1, NOW);
		expect(result.repetition).toBe(0);
		expect(result.interval).toBe(1);
		expect(result.easeFactor).toBeCloseTo(2.5 - 0.54, 10);
	});

	it("Grade 4 (Good) from rep=0: interval=1, rep=1, EF stays 2.50", () => {
		const current = makeState({ cardId: "c1" });
		const result = calculateNextReview(current, 4, NOW);
		expect(result.interval).toBe(1);
		expect(result.repetition).toBe(1);
		expect(result.easeFactor).toBeCloseTo(2.5, 10);
	});

	it("Grade 4 from rep=1: interval=6, rep=2, EF=2.50", () => {
		const current = makeState({ cardId: "c1", repetition: 1, interval: 1 });
		const result = calculateNextReview(current, 4, NOW);
		expect(result.interval).toBe(6);
		expect(result.repetition).toBe(2);
		expect(result.easeFactor).toBeCloseTo(2.5, 10);
	});

	it("Grade 4 from rep=2, interval=6, EF=2.5: interval=15, rep=3", () => {
		const current = makeState({ cardId: "c1", repetition: 2, interval: 6 });
		const result = calculateNextReview(current, 4, NOW);
		expect(result.interval).toBe(Math.round(6 * 2.5));
		expect(result.repetition).toBe(3);
	});

	it("Grade 5 (Easy) from initial: interval=1, rep=1, EF=2.60", () => {
		const current = makeState({ cardId: "c1" });
		const result = calculateNextReview(current, 5, NOW);
		expect(result.interval).toBe(1);
		expect(result.repetition).toBe(1);
		expect(result.easeFactor).toBeCloseTo(2.6, 10);
	});

	it("EF clamping: starting EF=1.3, grade 1 → EF clamped to 1.3", () => {
		const current = makeState({ cardId: "c1", easeFactor: MIN_EASE_FACTOR });
		const result = calculateNextReview(current, 1, NOW);
		expect(result.easeFactor).toBe(MIN_EASE_FACTOR);
	});

	it("Interval never drops to 0", () => {
		const current = makeState({ cardId: "c1", repetition: 2, interval: 1, easeFactor: MIN_EASE_FACTOR });
		const result = calculateNextReview(current, 4, NOW);
		expect(result.interval).toBeGreaterThanOrEqual(1);
	});

	it("Fractional rounding: rep=2, interval=7, EF=2.5 → 18", () => {
		const current = makeState({ cardId: "c1", repetition: 2, interval: 7 });
		const result = calculateNextReview(current, 4, NOW);
		expect(result.interval).toBe(Math.round(7 * 2.5));
	});

	it("Next review date calculation", () => {
		const current = makeState({ cardId: "c1" });
		const result = calculateNextReview(current, 4, NOW);
		const expected = new Date(NOW.getTime() + 1 * 24 * 60 * 60 * 1000).toISOString();
		expect(result.nextReviewDate).toBe(expected);
	});

	it("Lapse from high rep: grade 1 on rep=5, interval=60 → rep=0, interval=1, EF=1.96", () => {
		const current = makeState({ cardId: "c1", repetition: 5, interval: 60 });
		const result = calculateNextReview(current, 1, NOW);
		expect(result.repetition).toBe(0);
		expect(result.interval).toBe(1);
		expect(result.easeFactor).toBeCloseTo(1.96, 10);
	});

	it("Multi-step mixed grades: [4,5,4,1,4,5] starting EF=2.5", () => {
		const expectedEFs = [2.5, 2.6, 2.6, 2.06, 2.06, 2.16];
		const grades = [4, 5, 4, 1, 4, 5] as const;
		let state = makeState({ cardId: "c1" });

		for (let i = 0; i < grades.length; i++) {
			state = calculateNextReview(state, grades[i], NOW);
			expect(state.easeFactor).toBeCloseTo(expectedEFs[i], 10);
		}
	});
});

describe("isDue", () => {
	it("yesterday → true", () => {
		const yesterday = new Date(NOW.getTime() - 24 * 60 * 60 * 1000);
		const state = makeState({ cardId: "c1", nextReviewDate: yesterday.toISOString() });
		expect(isDue(state, NOW)).toBe(true);
	});

	it("now → true", () => {
		const state = makeState({ cardId: "c1", nextReviewDate: NOW.toISOString() });
		expect(isDue(state, NOW)).toBe(true);
	});

	it("tomorrow → false", () => {
		const tomorrow = new Date(NOW.getTime() + 24 * 60 * 60 * 1000);
		const state = makeState({ cardId: "c1", nextReviewDate: tomorrow.toISOString() });
		expect(isDue(state, NOW)).toBe(false);
	});
});

describe("getDueCards", () => {
	it("empty → empty", () => {
		expect(getDueCards([], new Map(), NOW)).toEqual([]);
	});

	it("all new cards respects limit", () => {
		const cards = Array.from({ length: 25 }, (_, i) => makeCard(`c${i}`));
		const result = getDueCards(cards, new Map(), NOW);
		expect(result.length).toBe(DEFAULT_MAX_NEW_CARDS_PER_SESSION);
	});

	it("mix of due/not-due/new", () => {
		const cards = [makeCard("due"), makeCard("notdue"), makeCard("new")];
		const yesterday = new Date(NOW.getTime() - 24 * 60 * 60 * 1000);
		const tomorrow = new Date(NOW.getTime() + 24 * 60 * 60 * 1000);
		const states = new Map<string, ReviewState>([
			["due", makeState({ cardId: "due", nextReviewDate: yesterday.toISOString() })],
			["notdue", makeState({ cardId: "notdue", nextReviewDate: tomorrow.toISOString() })],
		]);
		const result = getDueCards(cards, states, NOW);
		expect(result.map((c) => c.id)).toEqual(["due", "new"]);
	});

	it("due sorted ascending by nextReviewDate", () => {
		const cards = [makeCard("later"), makeCard("earlier")];
		const d1 = new Date(NOW.getTime() - 1 * 60 * 60 * 1000);
		const d2 = new Date(NOW.getTime() - 2 * 60 * 60 * 1000);
		const states = new Map<string, ReviewState>([
			["later", makeState({ cardId: "later", nextReviewDate: d1.toISOString() })],
			["earlier", makeState({ cardId: "earlier", nextReviewDate: d2.toISOString() })],
		]);
		const result = getDueCards(cards, states, NOW);
		expect(result.map((c) => c.id)).toEqual(["earlier", "later"]);
	});

	it("custom config limits new cards", () => {
		const cards = Array.from({ length: 10 }, (_, i) => makeCard(`c${i}`));
		const result = getDueCards(cards, new Map(), NOW, { maxNewCardsPerSession: 3 });
		expect(result.length).toBe(3);
	});
});

describe("countDueTomorrow", () => {
	it("cards due today/tomorrow counted, day-after not", () => {
		const tomorrow = new Date(NOW.getTime() + 24 * 60 * 60 * 1000);
		const dayAfter = new Date(NOW.getTime() + 2 * 24 * 60 * 60 * 1000);
		const states = new Map<string, ReviewState>([
			["today", makeState({ cardId: "today", nextReviewDate: NOW.toISOString() })],
			["tmrw", makeState({ cardId: "tmrw", nextReviewDate: tomorrow.toISOString() })],
			["later", makeState({ cardId: "later", nextReviewDate: dayAfter.toISOString() })],
		]);
		expect(countDueTomorrow(states, NOW)).toBe(2);
	});

	it("empty → 0", () => {
		expect(countDueTomorrow(new Map(), NOW)).toBe(0);
	});
});

