 1→{
 2→  "name": "flashcard-cli",
 3→  "version": "0.1.0",
 4→  "type": "module",
 5→  "scripts": {
 6→    "build": "bun build src/index.ts --outdir dist",
 7→    "lint": "biome check .",
 8→    "test": "bun test"
 9→  },
10→  "dependencies": {
11→    "typescript": "^5.4.0"
12→  },
13→  "devDependencies": {
14→    "@biomejs/biome": "^1.9.4"
15→  }
16→}

 1→{
 2→  "$schema": "https://biomejs.dev/schemas/1.9.4/schema.json",
 3→  "linter": {
 4→    "enabled": true,
 5→    "rules": {
 6→      "recommended": true
 7→    }
 8→  },
 9→  "organizeImports": {
10→    "enabled": true
11→  }
12→}

  1→import type { Card } from "./card";
  2→
  3→/** Numeric SM-2 grade: Again = 1, Good = 4, Easy = 5.
  4→ *
  5→ *  Grade mapping rationale: The standard SM-2 formula uses grades 0-5.
  6→ *  We map user input 1/2/3 to SM-2 grades 1/4/5 respectively.
  7→ *  Intermediate SM-2 grades 2 and 3 are skipped because:
  8→ *  - Grade 3 yields an EF delta of -0.14 per review, causing cards rated
  9→ *    "Good" to converge toward minimum ease after ~10 reviews.
 10→ *  - Grade 4 yields a delta of 0.0, preserving the current ease factor,
 11→ *    which better matches the intuition that "Good" means "on track."
 12→ *  - Grade 2 is too close to "Again" (grade 1) to be useful in a 3-button UI. */
 13→export type Grade = 1 | 4 | 5;
 14→
 15→/** SM-2 review state for a single card. */
 16→export interface ReviewState {
 17→	readonly cardId: string;
 18→	readonly repetition: number;
 19→	readonly easeFactor: number;
 20→	readonly interval: number;
 21→	readonly nextReviewDate: string; // ISO 8601
 22→}
 23→
 24→/** Configuration for the scheduling engine. */
 25→export interface ScheduleConfig {
 26→	readonly maxNewCardsPerSession: number;
 27→}
 28→
 29→/** Typed user input grade (1/2/3) before mapping to SM-2 Grade. */
 30→export type UserGrade = 1 | 2 | 3;
 31→
 32→export const DEFAULT_EASE_FACTOR = 2.5;
 33→export const MIN_EASE_FACTOR = 1.3;
 34→export const DEFAULT_MAX_NEW_CARDS_PER_SESSION = 20;
 35→
 36→/** Map user input grade (1/2/3) to SM-2 grade (1/4/5). */
 37→export function mapUserGrade(input: UserGrade): Grade {
 38→	const mapping: Record<UserGrade, Grade> = { 1: 1, 2: 4, 3: 5 };
 39→	return mapping[input];
 40→}
 41→
 42→/** Create initial review state for a new card. */
 43→export function createInitialReviewState(
 44→	cardId: string,
 45→	now: Date,
 46→): ReviewState {
 47→	return {
 48→		cardId,
 49→		repetition: 0,
 50→		easeFactor: DEFAULT_EASE_FACTOR,
 51→		interval: 0,
 52→		nextReviewDate: now.toISOString(),
 53→	};
 54→}
 55→
 56→/** Calculate next review state using SM-2 algorithm. */
 57→export function calculateNextReview(
 58→	current: ReviewState,
 59→	grade: Grade,
 60→	now: Date,
 61→): ReviewState {
 62→	const oldEF = current.easeFactor;
 63→	const newEF = Math.max(
 64→		MIN_EASE_FACTOR,
 65→		oldEF + (0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02)),
 66→	);
 67→
 68→	let interval: number;
 69→	let repetition: number;
 70→
 71→	if (grade < 3) {
 72→		// Again: reset
 73→		repetition = 0;
 74→		interval = 1;
 75→	} else {
 76→		if (current.repetition === 0) {
 77→			interval = 1;
 78→		} else if (current.repetition === 1) {
 79→			interval = 6;
 80→		} else {
 81→			interval = Math.max(1, Math.round(current.interval * newEF));
 82→		}
 83→		repetition = current.repetition + 1;
 84→	}
 85→
 86→	const nextReviewDate = new Date(
 87→		now.getTime() + interval * 24 * 60 * 60 * 1000,
 88→	).toISOString();
 89→
 90→	return {
 91→		cardId: current.cardId,
 92→		repetition,
 93→		easeFactor: newEF,
 94→		interval,
 95→		nextReviewDate,
 96→	};
 97→}
 98→
 99→/** Check if a card is due for review. */
100→export function isDue(state: ReviewState, now: Date): boolean {
101→	return now.getTime() >= new Date(state.nextReviewDate).getTime();
102→}
103→
104→/** Get cards that are due for review, including new cards up to session limit. */
105→export function getDueCards(
106→	cards: readonly Card[],
107→	reviewStates: ReadonlyMap<string, ReviewState>,
108→	now: Date,
109→	config?: Partial<ScheduleConfig>,
110→): Card[] {
111→	const maxNew =
112→		config?.maxNewCardsPerSession ?? DEFAULT_MAX_NEW_CARDS_PER_SESSION;
113→	const dueCards: Card[] = [];
