import type { ReviewState } from "./sm2";
import { rename, unlink } from "node:fs/promises";
import { dirname, join } from "node:path";

/**
 * Load review states from a JSON file.
 * Returns an empty Map if the file does not exist or is empty.
 * Invalid entries are skipped with a console.warn.
 * Throws if the file contains malformed JSON.
 */
export async function loadReviewStates(
	filePath: string,
): Promise<Map<string, ReviewState>> {
	const file = Bun.file(filePath);
	const exists = await file.exists();
	if (!exists) {
		return new Map();
	}

	const text = await file.text();
	if (!text.trim()) {
		return new Map();
	}

	let parsed: unknown;
	try {
		parsed = JSON.parse(text);
	} catch {
		throw new Error(`Failed to parse JSON from ${filePath}: malformed JSON`);
	}

	if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
		throw new Error(
			`Failed to parse JSON from ${filePath}: expected a JSON object`,
		);
	}

	const result = new Map<string, ReviewState>();
	const obj = parsed as Record<string, unknown>;

	for (const [key, value] of Object.entries(obj)) {
		if (!isValidReviewState(key, value)) {
			continue;
		}
		result.set(key, value as ReviewState);
	}

	return result;
}

function isValidReviewState(key: string, value: unknown): boolean {
	if (typeof value !== "object" || value === null || Array.isArray(value)) {
		console.warn(`Skipping entry "${key}": not a valid object`);
		return false;
	}

	const entry = value as Record<string, unknown>;

	if (typeof entry.cardId !== "string" || entry.cardId === "") {
		console.warn(`Skipping entry "${key}": cardId must be a non-empty string`);
		return false;
	}

	if (entry.cardId !== key) {
		console.warn(
			`Skipping entry "${key}": cardId "${entry.cardId}" does not match key`,
		);
		return false;
	}

	if (
		typeof entry.repetition !== "number" ||
		!Number.isInteger(entry.repetition) ||
		entry.repetition < 0
	) {
		console.warn(
			`Skipping entry "${key}": repetition must be a non-negative integer`,
		);
		return false;
	}

	if (typeof entry.easeFactor !== "number" || entry.easeFactor < 1.3) {
		console.warn(
			`Skipping entry "${key}": easeFactor must be a number >= 1.3`,
		);
		return false;
	}

	if (
		typeof entry.interval !== "number" ||
		!Number.isInteger(entry.interval) ||
		entry.interval < 0
	) {
		console.warn(
			`Skipping entry "${key}": interval must be a non-negative integer`,
		);
		return false;
	}

	if (typeof entry.nextReviewDate !== "string" || entry.nextReviewDate === "") {
		console.warn(
			`Skipping entry "${key}": nextReviewDate must be a non-empty string`,
		);
		return false;
	}

	const parsedDate = new Date(entry.nextReviewDate);
	if (Number.isNaN(parsedDate.getTime())) {
		console.warn(
			`Skipping entry "${key}": nextReviewDate is not a valid date`,
		);
		return false;
	}

	return true;
}

/**
 * Save review states to a JSON file atomically.
 * Writes to a temporary file first, then renames to the target path.
 */
export async function saveReviewStates(
	filePath: string,
	states: ReadonlyMap<string, ReviewState>,
): Promise<void> {
	const obj: Record<string, ReviewState> = {};
	for (const [key, value] of states) {
		obj[key] = value;
	}
	const json = JSON.stringify(obj, null, 2);

	const tempPath = `${filePath}.tmp`;
	await Bun.write(tempPath, json);
	try {
		await rename(tempPath, filePath);
	} catch (err) {
		await unlink(tempPath).catch(() => {});
		throw err;
	}
}

/**
 * Get the default reviews file path based on a cards file path.
 * Places `reviews.json` in the same directory as the cards file.
 */
export function getDefaultReviewsPath(cardsFilePath: string): string {
	return join(dirname(cardsFilePath), "reviews.json");
}

import { describe, expect, test, spyOn } from "bun:test";
import { mkdtemp, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import type { ReviewState } from "../src/sm2";
import {
	getDefaultReviewsPath,
	loadReviewStates,
	saveReviewStates,
} from "../src/storage";

function makeTmpDir(): Promise<string> {
	return mkdtemp(join(tmpdir(), "storage-test-"));
}

function makeState(
	cardId: string,
	overrides?: Partial<ReviewState>,
): ReviewState {
	return {
		cardId,
		repetition: 3,
		easeFactor: 2.5,
		interval: 6,
		nextReviewDate: "2026-04-01T00:00:00.000Z",
		...overrides,
	};
}

describe("loadReviewStates", () => {
	test("missing file returns empty Map", async () => {
		const dir = await makeTmpDir();
		const result = await loadReviewStates(join(dir, "nonexistent.json"));
		expect(result.size).toBe(0);
		await rm(dir, { recursive: true });
	});

	test("empty file returns empty Map", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		await writeFile(filePath, "");
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		await rm(dir, { recursive: true });
	});

	test("valid JSON with 2 entries", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: makeState("card1"),
			card2: makeState("card2", { easeFactor: 1.8, interval: 10 }),
		};
		await writeFile(filePath, JSON.stringify(data));
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(2);
		expect(result.get("card1")).toEqual(data.card1);
		expect(result.get("card2")).toEqual(data.card2);
		await rm(dir, { recursive: true });
	});

	test("invalid JSON throws", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		await writeFile(filePath, "{not valid json");
		await expect(loadReviewStates(filePath)).rejects.toThrow("malformed JSON");
		await rm(dir, { recursive: true });
	});

	test("entry with missing cardId is skipped with warning", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: {
				repetition: 3,
				easeFactor: 2.5,
				interval: 6,
				nextReviewDate: "2026-04-01T00:00:00.000Z",
			},
		};
		await writeFile(filePath, JSON.stringify(data));
		const spy = spyOn(console, "warn").mockImplementation(() => {});
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
		await rm(dir, { recursive: true });
	});

	test("easeFactor below 1.3 is skipped", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: makeState("card1", { easeFactor: 1.2 }),
		};
		await writeFile(filePath, JSON.stringify(data));
		const spy = spyOn(console, "warn").mockImplementation(() => {});
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
		await rm(dir, { recursive: true });
	});

	test("negative repetition is skipped", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: makeState("card1", { repetition: -1 }),
		};
		await writeFile(filePath, JSON.stringify(data));
		const spy = spyOn(console, "warn").mockImplementation(() => {});
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
		await rm(dir, { recursive: true });
	});

	test("invalid nextReviewDate is skipped", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: makeState("card1", { nextReviewDate: "not-a-date" }),
		};
		await writeFile(filePath, JSON.stringify(data));
		const spy = spyOn(console, "warn").mockImplementation(() => {});
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
		await rm(dir, { recursive: true });
	});

	test("key not matching cardId is skipped", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const data = {
			card1: makeState("card2"),
		};
		await writeFile(filePath, JSON.stringify(data));
		const spy = spyOn(console, "warn").mockImplementation(() => {});
		const result = await loadReviewStates(filePath);
		expect(result.size).toBe(0);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
		await rm(dir, { recursive: true });
	});
});

describe("saveReviewStates", () => {
	test("save then load round-trip", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const states = new Map<string, ReviewState>();
		states.set("card1", makeState("card1"));
		states.set("card2", makeState("card2", { interval: 10, easeFactor: 1.8 }));
		await saveReviewStates(filePath, states);
		const loaded = await loadReviewStates(filePath);
		expect(loaded.size).toBe(2);
		expect(loaded.get("card1")).toEqual(states.get("card1"));
		expect(loaded.get("card2")).toEqual(states.get("card2"));
		await rm(dir, { recursive: true });
	});

	test("overwrite existing file", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const states1 = new Map<string, ReviewState>();
		states1.set("card1", makeState("card1"));
		await saveReviewStates(filePath, states1);

		const states2 = new Map<string, ReviewState>();
		states2.set("card2", makeState("card2"));
		await saveReviewStates(filePath, states2);

		const loaded = await loadReviewStates(filePath);
		expect(loaded.size).toBe(1);
		expect(loaded.has("card1")).toBe(false);
		expect(loaded.get("card2")).toEqual(states2.get("card2"));
		await rm(dir, { recursive: true });
	});

	test("no .tmp file remains after success", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");
		const states = new Map<string, ReviewState>();
		states.set("card1", makeState("card1"));
		await saveReviewStates(filePath, states);
		const files = await readdir(dir);
		const tmpFiles = files.filter((f) => f.endsWith(".tmp"));
		expect(tmpFiles.length).toBe(0);
		await rm(dir, { recursive: true });
	});
});

describe("getDefaultReviewsPath", () => {
	test("./data/cards.json returns data/reviews.json", () => {
		const result = getDefaultReviewsPath("./data/cards.json");
		expect(result).toBe("data/reviews.json");
	});

	test("/absolute/path/deck.json returns /absolute/path/reviews.json", () => {
		const result = getDefaultReviewsPath("/absolute/path/deck.json");
		expect(result).toBe("/absolute/path/reviews.json");
	});
});

describe("round-trip integration", () => {
	test("create ReviewStates, save, load back, verify equality", async () => {
		const dir = await makeTmpDir();
		const filePath = join(dir, "reviews.json");

		const states = new Map<string, ReviewState>();
		states.set(
			"alpha",
			makeState("alpha", {
				repetition: 0,
				easeFactor: 2.5,
				interval: 0,
				nextReviewDate: "2026-03-15T12:00:00.000Z",
			}),
		);
		states.set(
			"beta",
			makeState("beta", {
				repetition: 5,
				easeFactor: 1.3,
				interval: 30,
				nextReviewDate: "2026-05-01T08:30:00.000Z",
			}),
		);
		states.set(
			"gamma",
			makeState("gamma", {
				repetition: 1,
				easeFactor: 2.1,
				interval: 6,
				nextReviewDate: "2026-04-10T00:00:00.000Z",
			}),
		);

		await saveReviewStates(filePath, states);
		const loaded = await loadReviewStates(filePath);

		expect(loaded.size).toBe(states.size);
		for (const [key, value] of states) {
			expect(loaded.get(key)).toEqual(value);
		}

		await rm(dir, { recursive: true });
	});
});

