import { describe, expect, it } from "bun:test";
import type { Card } from "../src/card";
import { currentCard, gradeCard, isQuizComplete, startQuiz } from "../src/quiz";
import type { ReviewState } from "../src/sm2";
import { DEFAULT_EASE_FACTOR, createInitialReviewState } from "../src/sm2";

const NOW = new Date("2026-01-01T00:00:00Z");

const testCard: Card = {
	id: "card-1",
	front: "Q1",
	back: "A1",
	tags: [],
	createdAt: "2026-01-01T00:00:00Z",
};

const testCard2: Card = {
	id: "card-2",
	front: "Q2",
	back: "A2",
	tags: [],
	createdAt: "2026-01-01T00:00:00Z",
};

describe("startQuiz", () => {
	it("initializes empty grades and updatedStates Maps, currentIndex 0", () => {
		const session = startQuiz([testCard]);
		expect(session.currentIndex).toBe(0);
		expect(session.grades.size).toBe(0);
		expect(session.updatedStates.size).toBe(0);
		expect(session.cards).toEqual([testCard]);
	});
});

describe("gradeCard", () => {
	it("with a new card (no prior review state) creates initial state and calculates next review", () => {
		const session = startQuiz([testCard]);
		const reviewStates = new Map<string, ReviewState>();

		gradeCard(session, 4, reviewStates, NOW);

		expect(session.grades.has("card-1")).toBe(true);
		expect(session.updatedStates.has("card-1")).toBe(true);
		const updatedState = session.updatedStates.get("card-1");
		expect(updatedState).toBeDefined();
		expect(updatedState?.cardId).toBe("card-1");
		expect(updatedState?.interval).toBeGreaterThan(0);
	});

	it("with an existing review state uses existing state", () => {
		const session = startQuiz([testCard]);
		const existingState: ReviewState = {
			cardId: "card-1",
			repetition: 2,
			easeFactor: 2.6,
			interval: 6,
			nextReviewDate: NOW.toISOString(),
		};
		const reviewStates = new Map<string, ReviewState>([
			["card-1", existingState],
		]);

		gradeCard(session, 4, reviewStates, NOW);

		const updatedState = session.updatedStates.get("card-1");
		expect(updatedState).toBeDefined();
		expect(updatedState?.cardId).toBe("card-1");
		// With repetition=2 and EF=2.6, interval should be round(6 * newEF)
		expect(updatedState?.repetition).toBe(3);
		expect(updatedState?.interval).toBeGreaterThan(1);
	});

	it("advances currentIndex", () => {
		const session = startQuiz([testCard, testCard2]);
		const reviewStates = new Map<string, ReviewState>();

		expect(session.currentIndex).toBe(0);
		gradeCard(session, 4, reviewStates, NOW);
		expect(session.currentIndex).toBe(1);
		gradeCard(session, 5, reviewStates, NOW);
		expect(session.currentIndex).toBe(2);
	});

	it("does nothing when no current card", () => {
		const session = startQuiz([]);
		const reviewStates = new Map<string, ReviewState>();

		gradeCard(session, 4, reviewStates, NOW);

		expect(session.grades.size).toBe(0);
		expect(session.updatedStates.size).toBe(0);
		expect(session.currentIndex).toBe(0);
	});

	it("stores correct Grade value in session.grades", () => {
		const session = startQuiz([testCard, testCard2]);
		const reviewStates = new Map<string, ReviewState>();

		gradeCard(session, 1, reviewStates, NOW);
		gradeCard(session, 5, reviewStates, NOW);

		expect(session.grades.get("card-1")).toBe(1);
		expect(session.grades.get("card-2")).toBe(5);
	});

	it("stores correct ReviewState in session.updatedStates", () => {
		const session = startQuiz([testCard]);
		const reviewStates = new Map<string, ReviewState>();

		gradeCard(session, 4, reviewStates, NOW);

		const state = session.updatedStates.get("card-1");
		expect(state).toBeDefined();
		expect(state?.cardId).toBe("card-1");
		expect(state?.interval).toBeGreaterThan(0);
		expect(state?.repetition).toBe(1);
		expect(state?.easeFactor).toBe(DEFAULT_EASE_FACTOR);
	});
});

describe("isQuizComplete", () => {
	it("returns true when all cards graded", () => {
		const session = startQuiz([testCard, testCard2]);
		const reviewStates = new Map<string, ReviewState>();

		expect(isQuizComplete(session)).toBe(false);
		gradeCard(session, 4, reviewStates, NOW);
		expect(isQuizComplete(session)).toBe(false);
		gradeCard(session, 4, reviewStates, NOW);
		expect(isQuizComplete(session)).toBe(true);
	});
});

