input.new_string:
export function formatScore(summary: ScoreSummary): string {
  return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
}

/** Review summary for a spaced-repetition session. */
export interface ReviewSummary {
  readonly totalReviewed: number;
  readonly againCount: number;
  readonly goodCount: number;
  readonly easyCount: number;
  readonly newCardsLearned: number;
  readonly dueTomorrow: number;
}

/** Calculate review summary from grades and review states. */
export function calculateReviewSummary(
  grades: ReadonlyMap<string, Grade>,
  previousStates: ReadonlyMap<string, ReviewState>,
  allStates: ReadonlyMap<string, ReviewState>,
  now: Date,
): ReviewSummary {
  const totalReviewed = grades.size;
  let againCount = 0;
  let goodCount = 0;
  let easyCount = 0;
  let newCardsLearned = 0;

  for (const [cardId, grade] of grades) {
    if (grade === 1) againCount++;
    else if (grade === 4) goodCount++;
    else if (grade === 5) easyCount++;

    if (!previousStates.has(cardId)) {
      newCardsLearned++;
    }
  }

  const dueTomorrow = countDueTomorrow(allStates, now);

  return {
    totalReviewed,
    againCount,
    goodCount,
    easyCount,
    newCardsLearned,
    dueTomorrow,
  };
}

/** Format a review summary as a human-readable string. */
export function formatReviewSummary(summary: ReviewSummary): string {
  return [
    "Session Summary",
    "\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500",
    `Reviewed: ${summary.totalReviewed} cards`,
    `Again: ${summary.againCount} | Good: ${summary.goodCount} | Easy: ${summary.easyCount}`,
    `New cards learned: ${summary.newCardsLearned}`,
    `Due tomorrow: ${summary.dueTomorrow}`,
  ].join("\n");
}

