import { describe, it, expect } from "bun:test";
import {
	calculateReviewSummary,
	formatReviewSummary,
	type ReviewSummary,
} from "../src/score";
import type { Grade, ReviewState } from "../src/sm2";

function makeState(
	cardId: string,
	nextReviewDate: string,
): ReviewState {
	return {
		cardId,
		repetition: 1,
		easeFactor: 2.5,
		interval: 1,
		nextReviewDate,
	};
}

describe("calculateReviewSummary", () => {
	it("counts grades correctly with a mix of again/good/easy", () => {
		const grades = new Map<string, Grade>([
			["c1", 1],
			["c2", 4],
			["c3", 5],
			["c4", 1],
			["c5", 4],
		]);
		const previousStates = new Map<string, ReviewState>(
			["c1", "c2", "c3", "c4", "c5"].map((id) => [
				id,
				makeState(id, "2026-01-01T00:00:00.000Z"),
			]),
		);
		const allStates = new Map<string, ReviewState>();
		const now = new Date("2026-04-04T12:00:00.000Z");

		const summary = calculateReviewSummary(grades, previousStates, allStates, now);

		expect(summary.totalReviewed).toBe(5);
		expect(summary.againCount).toBe(2);
		expect(summary.goodCount).toBe(2);
		expect(summary.easyCount).toBe(1);
	});

	it("identifies new cards not in previousStates", () => {
		const grades = new Map<string, Grade>([
			["c1", 4],
			["c2", 5],
			["c3", 1],
		]);
		const previousStates = new Map<string, ReviewState>([
			["c1", makeState("c1", "2026-01-01T00:00:00.000Z")],
		]);
		const allStates = new Map<string, ReviewState>();
		const now = new Date("2026-04-04T12:00:00.000Z");

		const summary = calculateReviewSummary(grades, previousStates, allStates, now);

		expect(summary.newCardsLearned).toBe(2);
	});

	it("computes dueTomorrow from allStates", () => {
		const now = new Date("2026-04-04T12:00:00.000Z");
		const grades = new Map<string, Grade>([["c1", 4]]);
		const previousStates = new Map<string, ReviewState>([
			["c1", makeState("c1", "2026-01-01T00:00:00.000Z")],
		]);
		// Two cards due within 24 hours, one card due later
		const allStates = new Map<string, ReviewState>([
			["c1", makeState("c1", "2026-04-05T10:00:00.000Z")],
			["c2", makeState("c2", "2026-04-04T14:00:00.000Z")],
			["c3", makeState("c3", "2026-04-10T00:00:00.000Z")],
		]);

		const summary = calculateReviewSummary(grades, previousStates, allStates, now);

		expect(summary.dueTomorrow).toBe(2);
	});

	it("returns all zeros with empty grades", () => {
		const grades = new Map<string, Grade>();
		const previousStates = new Map<string, ReviewState>();
		const allStates = new Map<string, ReviewState>();
		const now = new Date("2026-04-04T12:00:00.000Z");

		const summary = calculateReviewSummary(grades, previousStates, allStates, now);

		expect(summary.totalReviewed).toBe(0);
		expect(summary.againCount).toBe(0);
		expect(summary.goodCount).toBe(0);
		expect(summary.easyCount).toBe(0);
		expect(summary.newCardsLearned).toBe(0);
		expect(summary.dueTomorrow).toBe(0);
	});
});

describe("formatReviewSummary", () => {
	it("output contains expected strings", () => {
		const summary: ReviewSummary = {
			totalReviewed: 10,
			againCount: 2,
			goodCount: 5,
			easyCount: 3,
			newCardsLearned: 4,
			dueTomorrow: 7,
		};

		const output = formatReviewSummary(summary);

		expect(output).toContain("Session Summary");
		expect(output).toContain("Reviewed:");
		expect(output).toContain("Again:");
		expect(output).toContain("Good:");
		expect(output).toContain("Easy:");
		expect(output).toContain("New cards learned:");
		expect(output).toContain("Due tomorrow:");
	});
});

