  1→import { rename, unlink } from "node:fs/promises";
  2→import { dirname, join } from "node:path";
  3→import type { ReviewState } from "./sm2";
  4→
  5→/**
  6→ * Load review states from a JSON file.
  7→ * Returns an empty Map if the file does not exist or is empty.
  8→ * Invalid entries are skipped with a console.warn.
  9→ * Throws if the file contains malformed JSON.
 10→ */
 11→export async function loadReviewStates(
 12→	filePath: string,
 13→): Promise<Map<string, ReviewState>> {
 14→	const file = Bun.file(filePath);
 15→	const exists = await file.exists();
 16→	if (!exists) {
 17→		return new Map();
 18→	}
 19→
 20→	const text = await file.text();
 21→	if (!text.trim()) {
 22→		return new Map();
 23→	}
 24→
 25→	let parsed: unknown;
 26→	try {
 27→		parsed = JSON.parse(text);
 28→	} catch {
 29→		throw new Error(`Failed to parse JSON from ${filePath}: malformed JSON`);
 30→	}
 31→
 32→	if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
 33→		throw new Error(
 34→			`Failed to parse JSON from ${filePath}: expected a JSON object`,
 35→		);
 36→	}
 37→
 38→	const result = new Map<string, ReviewState>();
 39→	const obj = parsed as Record<string, unknown>;
 40→
 41→	for (const [key, value] of Object.entries(obj)) {
 42→		if (!isValidReviewState(key, value)) {
 43→			continue;
 44→		}
 45→		result.set(key, value as ReviewState);
 46→	}
 47→
 48→	return result;
 49→}
 50→
 51→function isValidReviewState(key: string, value: unknown): boolean {
 52→	if (typeof value !== "object" || value === null || Array.isArray(value)) {
 53→		console.warn(`Skipping entry "${key}": not a valid object`);
 54→		return false;
 55→	}
 56→
 57→	const entry = value as Record<string, unknown>;
 58→
 59→	if (typeof entry.cardId !== "string" || entry.cardId === "") {
 60→		console.warn(`Skipping entry "${key}": cardId must be a non-empty string`);
 61→		return false;
 62→	}
 63→
 64→	if (entry.cardId !== key) {
 65→		console.warn(
 66→			`Skipping entry "${key}": cardId "${entry.cardId}" does not match key`,
 67→		);
 68→		return false;
 69→	}
 70→
 71→	if (
 72→		typeof entry.repetition !== "number" ||
 73→		!Number.isInteger(entry.repetition) ||
 74→		entry.repetition < 0
 75→	) {
 76→		console.warn(
 77→			`Skipping entry "${key}": repetition must be a non-negative integer`,
 78→		);
 79→		return false;
 80→	}
 81→
 82→	if (typeof entry.easeFactor !== "number" || entry.easeFactor < 1.3) {
 83→		console.warn(`Skipping entry "${key}": easeFactor must be a number >= 1.3`);
 84→		return false;
 85→	}
 86→
 87→	if (
 88→		typeof entry.interval !== "number" ||
 89→		!Number.isInteger(entry.interval) ||
 90→		entry.interval < 0
 91→	) {
 92→		console.warn(
 93→			`Skipping entry "${key}": interval must be a non-negative integer`,
 94→		);
 95→		return false;
 96→	}
 97→
 98→	if (typeof entry.nextReviewDate !== "string" || entry.nextReviewDate === "") {
 99→		console.warn(
100→			`Skipping entry "${key}": nextReviewDate must be a non-empty string`,
101→		);
102→		return false;
103→	}
104→
105→	const parsedDate = new Date(entry.nextReviewDate);
106→	if (Number.isNaN(parsedDate.getTime())) {
107→		console.warn(`Skipping entry "${key}": nextReviewDate is not a valid date`);
108→		return false;
109→	}
110→
111→	return true;
112→}
113→
114→/**
115→ * Save review states to a JSON file atomically.
116→ * Writes to a temporary file first, then renames to the target path.
117→ */
118→export async function saveReviewStates(
119→	filePath: string,
120→	states: ReadonlyMap<string, ReviewState>,
121→): Promise<void> {
122→	const obj: Record<string, ReviewState> = {};
123→	for (const [key, value] of states) {
124→		obj[key] = value;
125→	}
126→	const json = JSON.stringify(obj, null, 2);
127→
128→	const tempPath = `${filePath}.tmp`;
129→	await Bun.write(tempPath, json);
130→	try {
131→		await rename(tempPath, filePath);
132→	} catch (err) {
133→		await unlink(tempPath).catch(() => {});
134→		throw err;
135→	}
136→}
