138→/**
139→ * Get the default reviews file path based on a cards file path.
140→ * Places `reviews.json` in the same directory as the cards file.
141→ */
142→export function getDefaultReviewsPath(cardsFilePath: string): string {
143→	return join(dirname(cardsFilePath), "reviews.json");
