 4→/** Score summary for a completed quiz session. */
 5→export interface ScoreSummary {
 6→	readonly total: number;
 7→	readonly correct: number;
 8→	readonly incorrect: number;
 9→	readonly percentage: number;
10→}
11→
12→/** Calculate score from a map of card ID -> correct/incorrect. */
13→export function calculateScore(answers: Map<string, boolean>): ScoreSummary {
14→	let correct = 0;
15→	let incorrect = 0;
16→	for (const [, isCorrect] of answers) {
17→		if (isCorrect) {
18→			correct++;
19→		} else {
20→			incorrect++;
21→		}
