 1→import { loadCards } from "./card";
 2→import { currentCard, gradeCard, isQuizComplete, startQuiz } from "./quiz";
 3→import { calculateReviewSummary, formatReviewSummary } from "./score";
 4→import { getDueCards, mapUserGrade } from "./sm2";
 5→import type { UserGrade } from "./sm2";
 6→import {
 7→	getDefaultReviewsPath,
 8→	loadReviewStates,
 9→	saveReviewStates,
10→} from "./storage";
11→
12→const CARDS_FILE = "./data/cards.json";
13→
14→/** Main CLI entry point. */
15→async function main(): Promise<void> {
16→	console.log("Flashcard CLI v0.1.0");
17→
18→	const cards = loadCards(CARDS_FILE);
19→	const reviewsPath = getDefaultReviewsPath(CARDS_FILE);
20→	const reviewStates = await loadReviewStates(reviewsPath);
21→	const previousStates = new Map(reviewStates); // snapshot before session
22→	const now = new Date();
23→
24→	const dueCards = getDueCards(cards, reviewStates, now);
25→	if (dueCards.length === 0) {
26→		console.log("No cards due for review.");
27→		return;
28→	}
29→
30→	const session = startQuiz(dueCards);
31→
32→	while (!isQuizComplete(session)) {
33→		const card = currentCard(session);
34→		if (!card) break;
35→
36→		console.log(`\nQ: ${card.front}`);
37→		prompt("Press Enter to reveal...");
38→		console.log(`A: ${card.back}`);
39→
40→		let gradeInput: string | null = null;
41→		while (true) {
42→			gradeInput = prompt("[1] Again  [2] Good  [3] Easy: ");
43→			if (gradeInput === null) {
44→				// EOF/Ctrl-D - end session early
45→				console.log("\nSession ended early.");
46→				break;
47→			}
48→			if (gradeInput === "1" || gradeInput === "2" || gradeInput === "3") {
49→				break;
50→			}
51→			console.log("Invalid choice, try again.");
52→		}
53→
54→		if (gradeInput === null) break;
55→
56→		const userGrade = Number(gradeInput) as UserGrade;
57→		const grade = mapUserGrade(userGrade);
58→		gradeCard(session, grade, reviewStates, now);
59→
60→		// Merge updated states into full review states and save
61→		for (const [cardId, state] of session.updatedStates) {
62→			reviewStates.set(cardId, state);
63→		}
64→		await saveReviewStates(reviewsPath, reviewStates);
65→	}
66→
67→	// Final save
68→	await saveReviewStates(reviewsPath, reviewStates);
69→
70→	// Show summary
71→	const summary = calculateReviewSummary(
72→		session.grades,
73→		previousStates,
74→		reviewStates,
75→		now,
76→	);
77→	console.log(`\n${formatReviewSummary(summary)}`);
78→}
79→
80→main();
