  1→import type { Card } from "./card";
  2→
  3→/** Numeric SM-2 grade: Again = 1, Good = 4, Easy = 5.
  4→ *
  5→ *  Grade mapping rationale: The standard SM-2 formula uses grades 0-5.
  6→ *  We map user input 1/2/3 to SM-2 grades 1/4/5 respectively.
  7→ *  Intermediate SM-2 grades 2 and 3 are skipped because:
  8→ *  - Grade 3 yields an EF delta of -0.14 per review, causing cards rated
  9→ *    "Good" to converge toward minimum ease after ~10 reviews.
 10→ *  - Grade 4 yields a delta of 0.0, preserving the current ease factor,
 11→ *    which better matches the intuition that "Good" means "on track."
 12→ *  - Grade 2 is too close to "Again" (grade 1) to be useful in a 3-button UI. */
 13→export type Grade = 1 | 4 | 5;
 14→
 15→/** SM-2 review state for a single card. */
 16→export interface ReviewState {
 17→	readonly cardId: string;
 18→	readonly repetition: number;
 19→	readonly easeFactor: number;
 20→	readonly interval: number;
 21→	readonly nextReviewDate: string; // ISO 8601
 22→}
 23→
 24→/** Configuration for the scheduling engine. */
 25→export interface ScheduleConfig {
 26→	readonly maxNewCardsPerSession: number;
 27→}
 28→
 29→/** Typed user input grade (1/2/3) before mapping to SM-2 Grade. */
 30→export type UserGrade = 1 | 2 | 3;
 31→
 32→export const DEFAULT_EASE_FACTOR = 2.5;
 33→export const MIN_EASE_FACTOR = 1.3;
 34→export const DEFAULT_MAX_NEW_CARDS_PER_SESSION = 20;
 35→
 36→/** Map user input grade (1/2/3) to SM-2 grade (1/4/5). */
 37→export function mapUserGrade(input: UserGrade): Grade {
 38→	const mapping: Record<UserGrade, Grade> = { 1: 1, 2: 4, 3: 5 };
 39→	return mapping[input];
 40→}
 41→
 42→/** Create initial review state for a new card. */
 43→export function createInitialReviewState(
 44→	cardId: string,
 45→	now: Date,
 46→): ReviewState {
 47→	return {
 48→		cardId,
 49→		repetition: 0,
 50→		easeFactor: DEFAULT_EASE_FACTOR,
 51→		interval: 0,
 52→		nextReviewDate: now.toISOString(),
 53→	};
 54→}
 55→
 56→/** Calculate next review state using SM-2 algorithm. */
 57→export function calculateNextReview(
 58→	current: ReviewState,
 59→	grade: Grade,
 60→	now: Date,
 61→): ReviewState {
 62→	const oldEF = current.easeFactor;
 63→	const newEF = Math.max(
 64→		MIN_EASE_FACTOR,
 65→		oldEF + (0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02)),
 66→	);
 67→
 68→	let interval: number;
 69→	let repetition: number;
 70→
 71→	if (grade < 3) {
 72→		// Again: reset
 73→		repetition = 0;
 74→		interval = 1;
 75→	} else {
 76→		if (current.repetition === 0) {
 77→			interval = 1;
 78→		} else if (current.repetition === 1) {
 79→			interval = 6;
 80→		} else {
 81→			interval = Math.max(1, Math.round(current.interval * newEF));
 82→		}
 83→		repetition = current.repetition + 1;
 84→	}
 85→
 86→	const nextReviewDate = new Date(
 87→		now.getTime() + interval * 24 * 60 * 60 * 1000,
 88→	).toISOString();
 89→
 90→	return {
 91→		cardId: current.cardId,
 92→		repetition,
 93→		easeFactor: newEF,
 94→		interval,
 95→		nextReviewDate,
 96→	};
 97→}
 98→
 99→/** Check if a card is due for review. */
100→export function isDue(state: ReviewState, now: Date): boolean {
101→	return now.getTime() >= new Date(state.nextReviewDate).getTime();
102→}
103→
104→/** Get cards that are due for review, including new cards up to session limit. */
105→export function getDueCards(
106→	cards: readonly Card[],
107→	reviewStates: ReadonlyMap<string, ReviewState>,
108→	now: Date,
109→	config?: Partial<ScheduleConfig>,
110→): Card[] {
111→	const maxNew =
112→		config?.maxNewCardsPerSession ?? DEFAULT_MAX_NEW_CARDS_PER_SESSION;
113→	const dueCards: Card[] = [];
114→	const newCards: Card[] = [];
115→
116→	for (const card of cards) {
117→		const state = reviewStates.get(card.id);
118→		if (!state) {
119→			newCards.push(card);
120→		} else if (isDue(state, now)) {
121→			dueCards.push(card);
122→		}
123→	}
124→
125→	dueCards.sort((a, b) => {
126→		const stateA = reviewStates.get(a.id) as ReviewState;
127→		const stateB = reviewStates.get(b.id) as ReviewState;
128→		return (
129→			new Date(stateA.nextReviewDate).getTime() -
130→			new Date(stateB.nextReviewDate).getTime()
131→		);
132→	});
133→
134→	return [...dueCards, ...newCards.slice(0, maxNew)];
135→}
136→
137→/** Count cards due by end of tomorrow (inclusive of already-overdue cards). */
138→export function countDueTomorrow(
139→	reviewStates: ReadonlyMap<string, ReviewState>,
140→	now: Date,
141→): number {
142→	const tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
143→	let count = 0;
144→	for (const state of reviewStates.values()) {
145→		if (new Date(state.nextReviewDate).getTime() <= tomorrow.getTime()) {
146→			count++;
147→		}
148→	}
149→	return count;
150→}
151→

  1→import { rename, unlink } from "node:fs/promises";
  2→import { dirname, join } from "node:path";
  3→import type { ReviewState } from "./sm2";
  4→
  5→/**
  6→ * Load review states from a JSON file.
  7→ * Returns an empty Map if the file does not exist or is empty.
  8→ * Invalid entries are skipped with a console.warn.
  9→ * Throws if the file contains malformed JSON.
 10→ */
 11→export async function loadReviewStates(
 12→	filePath: string,
 13→): Promise<Map<string, ReviewState>> {
 14→	const file = Bun.file(filePath);
 15→	const exists = await file.exists();
 16→	if (!exists) {
 17→		return new Map();
 18→	}
 19→
 20→	const text = await file.text();
 21→	if (!text.trim()) {
 22→		return new Map();
 23→	}
 24→
 25→	let parsed: unknown;
 26→	try {
 27→		parsed = JSON.parse(text);
 28→	} catch {
 29→		throw new Error(`Failed to parse JSON from ${filePath}: malformed JSON`);
 30→	}
 31→
 32→	if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
 33→		throw new Error(
 34→			`Failed to parse JSON from ${filePath}: expected a JSON object`,
 35→		);
 36→	}
 37→
 38→	const result = new Map<string, ReviewState>();
 39→	const obj = parsed as Record<string, unknown>;
 40→
 41→	for (const [key, value] of Object.entries(obj)) {
 42→		if (!isValidReviewState(key, value)) {
 43→			continue;
 44→		}
 45→		result.set(key, value as ReviewState);
 46→	}
 47→
 48→	return result;
 49→}
 50→
 51→function isValidReviewState(key: string, value: unknown): boolean {
 52→	if (typeof value !== "object" || value === null || Array.isArray(value)) {
 53→		console.warn(`Skipping entry "${key}": not a valid object`);
 54→		return false;
 55→	}
 56→
 57→	const entry = value as Record<string, unknown>;
 58→
 59→	if (typeof entry.cardId !== "string" || entry.cardId === "") {
 60→		console.warn(`Skipping entry "${key}": cardId must be a non-empty string`);
 61→		return false;
 62→	}
 63→
 64→	if (entry.cardId !== key) {
 65→		console.warn(
 66→			`Skipping entry "${key}": cardId "${entry.cardId}" does not match key`,
 67→		);
 68→		return false;
 69→	}
 70→
 71→	if (
 72→		typeof entry.repetition !== "number" ||
 73→		!Number.isInteger(entry.repetition) ||
 74→		entry.repetition < 0
 75→	) {
 76→		console.warn(
 77→			`Skipping entry "${key}": repetition must be a non-negative integer`,
 78→		);
 79→		return false;
 80→	}
 81→
 82→	if (typeof entry.easeFactor !== "number" || entry.easeFactor < 1.3) {
 83→		console.warn(`Skipping entry "${key}": easeFactor must be a number >= 1.3`);
 84→		return false;
 85→	}
 86→
 87→	if (
 88→		typeof entry.interval !== "number" ||
 89→		!Number.isInteger(entry.interval) ||
 90→		entry.interval < 0
 91→	) {
 92→		console.warn(
 93→			`Skipping entry "${key}": interval must be a non-negative integer`,
 94→		);
 95→		return false;
 96→	}
 97→
 98→	if (typeof entry.nextReviewDate !== "string" || entry.nextReviewDate === "") {
 99→		console.warn(
100→			`Skipping entry "${key}": nextReviewDate must be a non-empty string`,
101→		);
102→		return false;
103→	}
104→
105→	const parsedDate = new Date(entry.nextReviewDate);
106→	if (Number.isNaN(parsedDate.getTime())) {
107→		console.warn(`Skipping entry "${key}": nextReviewDate is not a valid date`);
108→		return false;
109→	}
110→
111→	return true;
112→}
113→
114→/**
115→ * Save review states to a JSON file atomically.
116→ * Writes to a temporary file first, then renames to the target path.
117→ */
118→export async function saveReviewStates(
119→	filePath: string,
120→	states: ReadonlyMap<string, ReviewState>,
121→): Promise<void> {
122→	const obj: Record<string, ReviewState> = {};
123→	for (const [key, value] of states) {
124→		obj[key] = value;
125→	}
126→	const json = JSON.stringify(obj, null, 2);
127→
128→	const tempPath = `${filePath}.tmp`;
129→	await Bun.write(tempPath, json);
130→	try {
131→		await rename(tempPath, filePath);
132→	} catch (err) {
133→		await unlink(tempPath).catch(() => {});
134→		throw err;
135→	}
136→}
137→
138→/**
139→ * Get the default reviews file path based on a cards file path.
140→ * Places `reviews.json` in the same directory as the cards file.
141→ */
142→export function getDefaultReviewsPath(cardsFilePath: string): string {
143→	return join(dirname(cardsFilePath), "reviews.json");
144→}
