 1→import type { Card } from "./card";
 2→import type { Grade, ReviewState } from "./sm2";
 3→import { calculateNextReview, createInitialReviewState } from "./sm2";
 4→
 5→/** Quiz session state. */
 6→export interface QuizSession {
 7→	readonly cards: readonly Card[];
 8→	currentIndex: number;
 9→	readonly grades: Map<string, Grade>;
10→	readonly updatedStates: Map<string, ReviewState>;
11→}
12→
13→/** Start a new quiz session with the given cards. */
14→export function startQuiz(cards: Card[]): QuizSession {
15→	return {
16→		cards,
17→		currentIndex: 0,
18→		grades: new Map(),
19→		updatedStates: new Map(),
20→	};
21→}
22→
23→/** Get the current card in the quiz, or undefined if done. */
24→export function currentCard(session: QuizSession): Card | undefined {
25→	return session.cards[session.currentIndex];
26→}
27→
28→/** Grade the current card using SM-2 and advance to the next card. */
29→export function gradeCard(
30→	session: QuizSession,
31→	grade: Grade,
32→	reviewStates: ReadonlyMap<string, ReviewState>,
33→	now: Date,
34→): void {
35→	const card = currentCard(session);
36→	if (!card) {
37→		return;
38→	}
39→	const existing = reviewStates.get(card.id);
40→	const state = existing ?? createInitialReviewState(card.id, now);
41→	const newState = calculateNextReview(state, grade, now);
42→	session.grades.set(card.id, grade);
43→	session.updatedStates.set(card.id, newState);
44→	session.currentIndex++;
45→}
46→
47→/** Check if the quiz is complete. */
48→export function isQuizComplete(session: QuizSession): boolean {
49→	return session.currentIndex >= session.cards.length;
50→}
51→

 1→import type { Grade, ReviewState } from "./sm2";
 2→import { countDueTomorrow } from "./sm2";
 3→
 4→/** Score summary for a completed quiz session. */
 5→export interface ScoreSummary {
 6→	readonly total: number;
 7→	readonly correct: number;
 8→	readonly incorrect: number;
 9→	readonly percentage: number;
10→}
11→
12→/** Calculate score from a map of card ID -> correct/incorrect. */
13→export function calculateScore(answers: Map<string, boolean>): ScoreSummary {
14→	let correct = 0;
15→	let incorrect = 0;
16→	for (const [, isCorrect] of answers) {
17→		if (isCorrect) {
18→			correct++;
19→		} else {
20→			incorrect++;
21→		}
22→	}
23→	const total = correct + incorrect;
24→	const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
25→	return { total, correct, incorrect, percentage };
26→}
27→
28→/** Format a score summary as a human-readable string. */
29→export function formatScore(summary: ScoreSummary): string {
30→	return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
31→}
32→
33→/** Review summary for a spaced-repetition session. */
34→export interface ReviewSummary {
35→	readonly totalReviewed: number;
36→	readonly againCount: number;
37→	readonly goodCount: number;
38→	readonly easyCount: number;
39→	readonly newCardsLearned: number;
40→	readonly dueTomorrow: number;
41→}
42→
43→/** Calculate review summary from grades and review states. */
44→export function calculateReviewSummary(
45→	grades: ReadonlyMap<string, Grade>,
46→	previousStates: ReadonlyMap<string, ReviewState>,
47→	allStates: ReadonlyMap<string, ReviewState>,
48→	now: Date,
49→): ReviewSummary {
50→	const totalReviewed = grades.size;
51→	let againCount = 0;
52→	let goodCount = 0;
53→	let easyCount = 0;
54→	let newCardsLearned = 0;
55→
56→	for (const [cardId, grade] of grades) {
57→		if (grade === 1) againCount++;
58→		else if (grade === 4) goodCount++;
59→		else if (grade === 5) easyCount++;
60→
61→		if (!previousStates.has(cardId)) {
62→			newCardsLearned++;
63→		}
64→	}
65→
66→	const dueTomorrow = countDueTomorrow(allStates, now);
67→
68→	return {
69→		totalReviewed,
70→		againCount,
71→		goodCount,
72→		easyCount,
73→		newCardsLearned,
74→		dueTomorrow,
75→	};
76→}
77→
78→/** Format a review summary as a human-readable string. */
79→export function formatReviewSummary(summary: ReviewSummary): string {
80→	return [
81→		"Session Summary",
82→		"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500",
83→		`Reviewed: ${summary.totalReviewed} cards`,
84→		`Again: ${summary.againCount} | Good: ${summary.goodCount} | Easy: ${summary.easyCount}`,
85→		`New cards learned: ${summary.newCardsLearned}`,
86→		`Due tomorrow: ${summary.dueTomorrow}`,
87→	].join("\n");
88→}
89→

 1→import { loadCards } from "./card";
 2→import { currentCard, gradeCard, isQuizComplete, startQuiz } from "./quiz";
 3→import { calculateReviewSummary, formatReviewSummary } from "./score";
 4→import { getDueCards, mapUserGrade } from "./sm2";
 5→import type { UserGrade } from "./sm2";
 6→import {
 7→	getDefaultReviewsPath,
 8→	loadReviewStates,
 9→	saveReviewStates,
10→} from "./storage";
11→
12→const CARDS_FILE = "./data/cards.json";
13→
14→/** Main CLI entry point. */
15→async function main(): Promise<void> {
16→	console.log("Flashcard CLI v0.1.0");
17→
18→	const cards = loadCards(CARDS_FILE);
19→	const reviewsPath = getDefaultReviewsPath(CARDS_FILE);
20→	const reviewStates = await loadReviewStates(reviewsPath);
21→	const previousStates = new Map(reviewStates); // snapshot before session
22→	const now = new Date();
23→
24→	const dueCards = getDueCards(cards, reviewStates, now);
25→	if (dueCards.length === 0) {
26→		console.log("No cards due for review.");
27→		return;
28→	}
29→
30→	const session = startQuiz(dueCards);
31→
32→	while (!isQuizComplete(session)) {
33→		const card = currentCard(session);
34→		if (!card) break;
35→
36→		console.log(`\nQ: ${card.front}`);
37→		prompt("Press Enter to reveal...");
38→		console.log(`A: ${card.back}`);
39→
40→		let gradeInput: string | null = null;
41→		while (true) {
42→			gradeInput = prompt("[1] Again  [2] Good  [3] Easy: ");
43→			if (gradeInput === null) {
44→				// EOF/Ctrl-D - end session early
45→				console.log("\nSession ended early.");
46→				break;
47→			}
48→			if (gradeInput === "1" || gradeInput === "2" || gradeInput === "3") {
49→				break;
50→			}
51→			console.log("Invalid choice, try again.");
52→		}
53→
54→		if (gradeInput === null) break;
55→
56→		const userGrade = Number(gradeInput) as UserGrade;
57→		const grade = mapUserGrade(userGrade);
58→		gradeCard(session, grade, reviewStates, now);
59→
60→		// Merge updated states into full review states and save
61→		for (const [cardId, state] of session.updatedStates) {
62→			reviewStates.set(cardId, state);
63→		}
64→		await saveReviewStates(reviewsPath, reviewStates);
65→	}
66→
67→	// Final save
68→	await saveReviewStates(reviewsPath, reviewStates);
69→
70→	// Show summary
71→	const summary = calculateReviewSummary(
72→		session.grades,
73→		previousStates,
74→		reviewStates,
75→		now,
76→	);
77→	console.log(`\n${formatReviewSummary(summary)}`);
78→}
79→
80→main();
