12→// src/quiz.ts
13→function startQuiz(cards) {
14→  return {
15→    cards,
16→    currentIndex: 0,
17→    answers: new Map
18→  };
19→}
20→function currentCard(session) {
21→  return session.cards[session.currentIndex];
22→}
23→function answerCard(session, correct) {
24→  const card = currentCard(session);
25→  if (card) {
26→    session.answers.set(card.id, correct);
27→    session.currentIndex++;
28→  }
29→}
30→function isQuizComplete(session) {
31→  return session.currentIndex >= session.cards.length;
32→}
