34→// src/score.ts
35→function calculateScore(answers) {
36→  let correct = 0;
37→  let incorrect = 0;
38→  for (const [, isCorrect] of answers) {
39→    if (isCorrect) {
40→      correct++;
41→    } else {
42→      incorrect++;
43→    }
44→  }
45→  const total = correct + incorrect;
46→  const percentage = total > 0 ? Math.round(correct / total * 100) : 0;
47→  return { total, correct, incorrect, percentage };
48→}
49→function formatScore(summary) {
50→  return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
51→}
