input.new_string:
/** Apply default SM-2 review fields to a card loaded from JSON.
 *  Also validates/clamps SM-2 fields to ensure data integrity
 *  (e.g., corrupted or hand-edited JSON). */
function applyReviewDefaults(raw: Partial<Card> & Pick<Card, 'id' | 'front' | 'back'>): Card {
  const ef = raw.easinessFactor ?? 2.5;
  const interval = raw.interval ?? 0;
  const reps = raw.repetitions ?? 0;
  return {
    id: raw.id,
    front: raw.front,
    back: raw.back,
    tags: raw.tags ?? [],
    createdAt: raw.createdAt ?? new Date().toISOString(),
    easinessFactor: Math.max(ef, 1.3),   // EF must be >= 1.3
    interval: Math.max(interval, 0),      // interval must be >= 0
    repetitions: Math.max(reps, 0),       // repetitions must be >= 0
    nextReviewDate: raw.nextReviewDate ?? null,
    lastReviewDate: raw.lastReviewDate ?? null,
  };
}

