### `answerCard(session: QuizSession, correct: boolean): QuizSession`

**Signature change**: Now returns a new `QuizSession` instead of mutating in-place (immutable pattern).

**Behavior change**: Maps the boolean to an SM-2 quality grade before storing:
- `correct === true` -> quality `4` ("correct after hesitation" -- conservative)
- `correct === false` -> quality `1` ("incorrect; recognized answer")

```typescript
export function answerCard(session: QuizSession, correct: boolean): QuizSession {
  const card = currentCard(session);
  if (!card) return session;
  const quality = correct ? QUALITY_CORRECT : QUALITY_INCORRECT;
  const newAnswers = new Map(session.answers);
  newAnswers.set(card.id, quality);
  return {
    cards: session.cards,
    currentIndex: session.currentIndex + 1,
    answers: newAnswers,
  };
}

