/** SM-2 review state for a single card. */
export interface SM2State {
  readonly easinessFactor: number;
  readonly interval: number;
  readonly repetitions: number;
}

/** Result of an SM-2 calculation, includes the new state and next review date. */
export interface SM2Result {
  readonly state: SM2State;
  readonly nextReviewDate: string | null;
}

const DEFAULT_EASINESS_FACTOR = 2.5;
const MIN_EASINESS_FACTOR = 1.3;
const INITIAL_INTERVAL_FIRST = 1;
const INITIAL_INTERVAL_SECOND = 6;

/** Quality grade at or above which a recall is considered successful. */
export const QUALITY_PASS_THRESHOLD = 3;

/** Returns the default SM-2 state for a new/unreviewed card. */
export function getDefaultSM2State(): SM2State {
  return {
    easinessFactor: DEFAULT_EASINESS_FACTOR,
    interval: 0,
    repetitions: 0,
  };
}

/** Core SM-2 algorithm: computes updated state and next review date. */
export function calculateSM2(
  state: SM2State,
  quality: number,
  today: string,
): SM2Result {
  let repetitions: number;
  let interval: number;

  if (quality >= QUALITY_PASS_THRESHOLD) {
    if (state.repetitions === 0) {
      interval = INITIAL_INTERVAL_FIRST;
    } else if (state.repetitions === 1) {
      interval = INITIAL_INTERVAL_SECOND;
    } else {
      interval = Math.round(state.interval * state.easinessFactor);
    }
    repetitions = state.repetitions + 1;
  } else {
    repetitions = 0;
    interval = INITIAL_INTERVAL_FIRST;
  }

  const ef = Math.max(
    state.easinessFactor +
      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
    MIN_EASINESS_FACTOR,
  );

  const nextReviewDate = addDays(today, interval);

  return {
    state: { easinessFactor: ef, interval, repetitions },
    nextReviewDate,
  };
}

/** Determines if a card is due for review. */
export function isDue(nextReviewDate: string | null, today: string): boolean {
  if (nextReviewDate === null) {
    return true;
  }
  return today >= nextReviewDate;
}

/** Formats a Date object as a YYYY-MM-DD string using UTC. */
export function formatDateAsISO(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** Adds a number of days to a YYYY-MM-DD date string, returning a new YYYY-MM-DD string. */
export function addDays(dateStr: string, days: number): string {
  const date = new Date(`${dateStr}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return formatDateAsISO(date);
}

