import { describe, expect, it } from "bun:test";
import {
  addDays,
  calculateSM2,
  formatDateAsISO,
  getDefaultSM2State,
} from "../src/sm2";

describe("getDefaultSM2State", () => {
  it("returns EF 2.5, interval 0, repetitions 0", () => {
    const state = getDefaultSM2State();
    expect(state.easinessFactor).toBe(2.5);
    expect(state.interval).toBe(0);
    expect(state.repetitions).toBe(0);
  });
});

describe("calculateSM2", () => {
  const today = "2026-04-04";

  it("first correct review: interval=1, repetitions=1", () => {
    const state = getDefaultSM2State();
    const result = calculateSM2(state, 4, today);
    expect(result.state.interval).toBe(1);
    expect(result.state.repetitions).toBe(1);
    expect(result.nextReviewDate).toBe("2026-04-05");
  });

  it("second correct review: interval=6, repetitions=2", () => {
    const state = { easinessFactor: 2.5, interval: 1, repetitions: 1 };
    const result = calculateSM2(state, 4, today);
    expect(result.state.interval).toBe(6);
    expect(result.state.repetitions).toBe(2);
    expect(result.nextReviewDate).toBe("2026-04-10");
  });

  it("third correct review: interval=round(6*EF), repetitions=3", () => {
    const state = { easinessFactor: 2.5, interval: 6, repetitions: 2 };
    const result = calculateSM2(state, 4, today);
    expect(result.state.interval).toBe(15);
    expect(result.state.repetitions).toBe(3);
  });

  it("fourth correct review with EF 2.5: interval=round(15*2.5)=38", () => {
    const state = { easinessFactor: 2.5, interval: 15, repetitions: 3 };
    const result = calculateSM2(state, 4, today);
    expect(result.state.interval).toBe(38);
    expect(result.state.repetitions).toBe(4);
  });

  it("quality 4 progression matches reference table", () => {
    let state = getDefaultSM2State();

    // Review 1
    let result = calculateSM2(state, 4, today);
    expect(result.state.easinessFactor).toBe(2.5);
    expect(result.state.interval).toBe(1);
    expect(result.state.repetitions).toBe(1);
    state = result.state;

    // Review 2
    result = calculateSM2(state, 4, "2026-04-05");
    expect(result.state.easinessFactor).toBe(2.5);
    expect(result.state.interval).toBe(6);
    expect(result.state.repetitions).toBe(2);
    state = result.state;

    // Review 3
    result = calculateSM2(state, 4, "2026-04-11");
    expect(result.state.easinessFactor).toBe(2.5);
    expect(result.state.interval).toBe(15);
    expect(result.state.repetitions).toBe(3);
    state = result.state;

    // Review 4
    result = calculateSM2(state, 4, "2026-04-26");
    expect(result.state.easinessFactor).toBe(2.5);
    expect(result.state.interval).toBe(38);
    expect(result.state.repetitions).toBe(4);
  });

  it("failed review resets repetitions to 0 and interval to 1", () => {
    const state = { easinessFactor: 2.5, interval: 15, repetitions: 3 };
    const result = calculateSM2(state, 1, today);
    expect(result.state.repetitions).toBe(0);
    expect(result.state.interval).toBe(1);
    expect(result.nextReviewDate).toBe("2026-04-05");
  });
});

describe("addDays", () => {
  it("adds days correctly", () => {
    expect(addDays("2026-04-04", 5)).toBe("2026-04-09");
  });

  it("handles month boundaries", () => {
    expect(addDays("2026-04-28", 5)).toBe("2026-05-03");
  });

  it("handles year boundaries", () => {
    expect(addDays("2026-12-30", 5)).toBe("2027-01-04");
  });

  it("adds 0 days returns same date", () => {
    expect(addDays("2026-04-04", 0)).toBe("2026-04-04");
  });

  it("handles leap year boundaries (Feb 28-29)", () => {
    // 2028 is a leap year
    expect(addDays("2028-02-28", 1)).toBe("2028-02-29");
    expect(addDays("2028-02-28", 2)).toBe("2028-03-01");
    // 2027 is not a leap year
    expect(addDays("2027-02-28", 1)).toBe("2027-03-01");
  });
});

describe("formatDateAsISO", () => {
  it("formats Date as YYYY-MM-DD", () => {
    const date = new Date("2026-04-04T12:00:00Z");
    expect(formatDateAsISO(date)).toBe("2026-04-04");
  });

  it("uses UTC to avoid timezone shifts", () => {
    // A date at 23:00 UTC on April 3rd should still format as April 3rd
    const date = new Date("2026-04-03T23:00:00Z");
    expect(formatDateAsISO(date)).toBe("2026-04-03");
  });
});

