 1→/** SM-2 review state for a single card. */
 2→export interface SM2State {
 3→  readonly easinessFactor: number;
 4→  readonly interval: number;
 5→  readonly repetitions: number;
 6→}
 7→
 8→/** Result of an SM-2 calculation, includes the new state and next review date. */
 9→export interface SM2Result {
10→  readonly state: SM2State;
11→  readonly nextReviewDate: string | null;
12→}
13→
14→const DEFAULT_EASINESS_FACTOR = 2.5;
15→const MIN_EASINESS_FACTOR = 1.3;
16→const INITIAL_INTERVAL_FIRST = 1;
17→const INITIAL_INTERVAL_SECOND = 6;
18→
19→/** Quality grade at or above which a recall is considered successful. */
20→export const QUALITY_PASS_THRESHOLD = 3;
21→
22→/** Returns the default SM-2 state for a new/unreviewed card. */
23→export function getDefaultSM2State(): SM2State {
24→  return {
25→    easinessFactor: DEFAULT_EASINESS_FACTOR,
26→    interval: 0,
27→    repetitions: 0,
28→  };
29→}
30→
31→/** Core SM-2 algorithm: computes updated state and next review date. */
32→export function calculateSM2(
33→  state: SM2State,
34→  quality: number,
35→  today: string,
36→): SM2Result {
37→  let repetitions: number;
38→  let interval: number;
39→
40→  if (quality >= QUALITY_PASS_THRESHOLD) {
41→    if (state.repetitions === 0) {
42→      interval = INITIAL_INTERVAL_FIRST;
43→    } else if (state.repetitions === 1) {
44→      interval = INITIAL_INTERVAL_SECOND;
45→    } else {
46→      interval = Math.round(state.interval * state.easinessFactor);
47→    }
48→    repetitions = state.repetitions + 1;
49→  } else {
50→    repetitions = 0;
51→    interval = INITIAL_INTERVAL_FIRST;
52→  }
53→
54→  const ef = Math.max(
55→    state.easinessFactor +
56→      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
57→    MIN_EASINESS_FACTOR,
58→  );
59→
60→  const nextReviewDate = addDays(today, interval);
61→
62→  return {
63→    state: { easinessFactor: ef, interval, repetitions },
64→    nextReviewDate,
65→  };
66→}
67→
68→/** Determines if a card is due for review. */
69→export function isDue(nextReviewDate: string | null, today: string): boolean {
70→  if (nextReviewDate === null) {
71→    return true;
72→  }
73→  return today >= nextReviewDate;
74→}
75→
76→/** Formats a Date object as a YYYY-MM-DD string using UTC. */
77→export function formatDateAsISO(date: Date): string {
78→  return date.toISOString().slice(0, 10);
79→}
80→
81→/** Adds a number of days to a YYYY-MM-DD date string, returning a new YYYY-MM-DD string. */
82→export function addDays(dateStr: string, days: number): string {
83→  const date = new Date(`${dateStr}T00:00:00Z`);
84→  date.setUTCDate(date.getUTCDate() + days);
85→  return formatDateAsISO(date);
86→}
