  1→/** SM-2 review state for a single card. */
  2→export interface SM2State {
  3→  readonly easinessFactor: number;
  4→  readonly interval: number;
  5→  readonly repetitions: number;
  6→}
  7→
  8→/** Result of an SM-2 calculation, includes the new state and next review date. */
  9→export interface SM2Result {
 10→  readonly state: SM2State;
 11→  readonly nextReviewDate: string | null;
 12→}
 13→
 14→const DEFAULT_EASINESS_FACTOR = 2.5;
 15→const MIN_EASINESS_FACTOR = 1.3;
 16→const INITIAL_INTERVAL_FIRST = 1;
 17→const INITIAL_INTERVAL_SECOND = 6;
 18→
 19→/** Quality grade at or above which a recall is considered successful. */
 20→export const QUALITY_PASS_THRESHOLD = 3;
 21→
 22→/** Returns the default SM-2 state for a new/unreviewed card. */
 23→export function getDefaultSM2State(): SM2State {
 24→  return {
 25→    easinessFactor: DEFAULT_EASINESS_FACTOR,
 26→    interval: 0,
 27→    repetitions: 0,
 28→  };
 29→}
 30→
 31→/** Core SM-2 algorithm: computes updated state and next review date. */
 32→export function calculateSM2(
 33→  state: SM2State,
 34→  quality: number,
 35→  today: string,
 36→): SM2Result {
 37→  if (!Number.isInteger(quality)) {
 38→    throw new Error(`Invalid quality: expected integer, got ${quality}`);
 39→  }
 40→  if (quality < 0 || quality > 5) {
 41→    throw new Error(`Invalid quality: expected 0-5, got ${quality}`);
 42→  }
 43→
 44→  let repetitions: number;
 45→  let interval: number;
 46→
 47→  if (quality >= QUALITY_PASS_THRESHOLD) {
 48→    if (state.repetitions === 0) {
 49→      interval = INITIAL_INTERVAL_FIRST;
 50→    } else if (state.repetitions === 1) {
 51→      interval = INITIAL_INTERVAL_SECOND;
 52→    } else {
 53→      interval = Math.round(state.interval * state.easinessFactor);
 54→    }
 55→    repetitions = state.repetitions + 1;
 56→  } else {
 57→    repetitions = 0;
 58→    interval = INITIAL_INTERVAL_FIRST;
 59→  }
 60→
 61→  const ef = Math.max(
 62→    state.easinessFactor +
 63→      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
 64→    MIN_EASINESS_FACTOR,
 65→  );
 66→
 67→  const nextReviewDate = addDays(today, interval);
 68→
 69→  return {
 70→    state: { easinessFactor: ef, interval, repetitions },
 71→    nextReviewDate,
 72→  };
 73→}
 74→
 75→/** Determines if a card is due for review. */
 76→export function isDue(nextReviewDate: string | null, today: string): boolean {
 77→  if (nextReviewDate === null) {
 78→    return true;
 79→  }
 80→  return today >= nextReviewDate;
 81→}
 82→
 83→/** Formats a Date object as a YYYY-MM-DD string using UTC. */
 84→export function formatDateAsISO(date: Date): string {
 85→  return date.toISOString().slice(0, 10);
 86→}
 87→
 88→/** Adds a number of days to a YYYY-MM-DD date string, returning a new YYYY-MM-DD string. */
 89→export function addDays(dateStr: string, days: number): string {
 90→  if (days < 0) {
 91→    throw new Error(
 92→      `Invalid days: expected non-negative integer, got ${days}`,
 93→    );
 94→  }
 95→  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
 96→    throw new Error(
 97→      `Invalid date format: expected YYYY-MM-DD, got ${dateStr}`,
 98→    );
 99→  }
100→  const date = new Date(`${dateStr}T00:00:00Z`);
101→  date.setUTCDate(date.getUTCDate() + days);
102→  return formatDateAsISO(date);
103→}
