// --- Phase 3: Property-based tests, isDue, lifecycle ---

/**
 * Simple seeded linear congruential generator for reproducible random numbers.
 * Parameters from Numerical Recipes.
 */
function seededRng(seed: number): () => number {
  let s = seed;
  return () => {
    s = (s * 1664525 + 1013904223) & 0xffffffff;
    return (s >>> 0) / 0x100000000;
  };
}

describe("calculateSM2 — property-based invariants", () => {
  const rng = seededRng(42);
  const today = "2026-04-04";

  it("EF is always >= 1.3 for any valid quality sequence", () => {
    for (let i = 0; i < 120; i++) {
      let state: SM2State = getDefaultSM2State();
      const seqLen = Math.floor(rng() * 20) + 1;
      for (let j = 0; j < seqLen; j++) {
        const quality = Math.floor(rng() * 6); // 0-5
        const result = calculateSM2(state, quality, today);
        expect(result.state.easinessFactor).toBeGreaterThanOrEqual(1.3);
        state = result.state;
      }
    }
  });

  it("interval is always >= 1 after any review", () => {
    const rng2 = seededRng(123);
    for (let i = 0; i < 120; i++) {
      let state: SM2State = getDefaultSM2State();
      const seqLen = Math.floor(rng2() * 20) + 1;
      for (let j = 0; j < seqLen; j++) {
        const quality = Math.floor(rng2() * 6);
        const result = calculateSM2(state, quality, today);
        expect(result.state.interval).toBeGreaterThanOrEqual(1);
        state = result.state;
      }
    }
  });

  it("repetitions is non-negative after any review", () => {
    const rng3 = seededRng(999);
    for (let i = 0; i < 120; i++) {
      let state: SM2State = getDefaultSM2State();
      const seqLen = Math.floor(rng3() * 20) + 1;
      for (let j = 0; j < seqLen; j++) {
        const quality = Math.floor(rng3() * 6);
        const result = calculateSM2(state, quality, today);
        expect(result.state.repetitions).toBeGreaterThanOrEqual(0);
        state = result.state;
      }
    }
  });

  it("intervals are non-decreasing for consecutive reviews with any constant quality >= 3", () => {
    for (const quality of [3, 4, 5]) {
      let state: SM2State = getDefaultSM2State();
      let prevInterval = 0;
      for (let j = 0; j < 20; j++) {
        const result = calculateSM2(state, quality, today);
        expect(result.state.interval).toBeGreaterThanOrEqual(prevInterval);
        prevInterval = result.state.interval;
        state = result.state;
      }
    }
  });

  it("computes correct nextReviewDate", () => {
    const rng4 = seededRng(777);
    for (let i = 0; i < 120; i++) {
      let state: SM2State = getDefaultSM2State();
      const quality = Math.floor(rng4() * 6);
      const result = calculateSM2(state, quality, today);
      const expected = addDays(today, result.state.interval);
      expect(result.nextReviewDate).toBe(expected);
    }
  });
});

describe("isDue", () => {
  it("returns true for null nextReviewDate", () => {
    expect(isDue(null, "2026-04-04")).toBe(true);
  });

  it("returns true for past date", () => {
    expect(isDue("2026-04-01", "2026-04-04")).toBe(true);
  });

  it("returns true for today's date", () => {
    expect(isDue("2026-04-04", "2026-04-04")).toBe(true);
  });

  it("returns false for future date", () => {
    expect(isDue("2026-04-10", "2026-04-04")).toBe(false);
  });
});

describe("calculateSM2 — end-to-end lifecycle", () => {
  it("full lifecycle: new card through 5 reviews with varying quality", () => {
    let state: SM2State = getDefaultSM2State();
    let currentDate = "2026-04-04";

    // Review 1: quality 4 (pass)
    let result = calculateSM2(state, 4, currentDate);
    expect(result.state.repetitions).toBe(1);
    expect(result.state.interval).toBe(1);
    expect(result.state.easinessFactor).toBe(2.5);
    state = result.state;
    currentDate = result.nextReviewDate!;

    // Review 2: quality 5 (strong pass)
    result = calculateSM2(state, 5, currentDate);
    expect(result.state.repetitions).toBe(2);
    expect(result.state.interval).toBe(6);
    expect(result.state.easinessFactor).toBeCloseTo(2.6, 10);
    state = result.state;
    currentDate = result.nextReviewDate!;

    // Review 3: quality 2 (fail — resets)
    result = calculateSM2(state, 2, currentDate);
    expect(result.state.repetitions).toBe(0);
    expect(result.state.interval).toBe(1);
    // EF updated even on failure: 2.6 + (0.1 - 3*(0.08+3*0.02)) = 2.6 - 0.32 = 2.28
    expect(result.state.easinessFactor).toBeCloseTo(2.18, 2);
    state = result.state;
    currentDate = result.nextReviewDate!;

    // Review 4: quality 3 (pass, barely)
    result = calculateSM2(state, 3, currentDate);
    expect(result.state.repetitions).toBe(1);
    expect(result.state.interval).toBe(1);
    // EF: 2.18 + (0.1 - 2*(0.08+2*0.02)) = 2.18 - 0.14 = 2.04
    expect(result.state.easinessFactor).toBeCloseTo(2.04, 2);
    state = result.state;
    currentDate = result.nextReviewDate!;

    // Review 5: quality 4 (pass, continues)
    result = calculateSM2(state, 4, currentDate);
    expect(result.state.repetitions).toBe(2);
    expect(result.state.interval).toBe(6);
    // EF: 2.04 + 0 = 2.04
    expect(result.state.easinessFactor).toBeCloseTo(2.04, 2);
    state = result.state;

    // Verify the final nextReviewDate is 6 days from the last review
    expect(result.nextReviewDate).toBe(addDays(currentDate, 6));
  });
});

