input.new_string:
/**
 * SM-2 review state for a single card.
 * Tracks the easiness factor, current interval in days, and number of consecutive correct repetitions.
 */
export interface SM2State {
  /** Easiness factor (EF), always >= 1.3. Higher values mean the card is easier to recall. */
  readonly easinessFactor: number;
  /** Current inter-repetition interval in days. 0 means unreviewed; >= 1 after any review. */
  readonly interval: number;
  /** Number of consecutive correct (quality >= 3) repetitions. Resets to 0 on failure. */
  readonly repetitions: number;
}

/**
 * Result of an SM-2 calculation, including the updated state and the next scheduled review date.
 */
export interface SM2Result {
  /** The updated SM-2 state after the review. */
  readonly state: SM2State;
  /** Next review date as a YYYY-MM-DD string, or null for the pre-first-review state. */
  readonly nextReviewDate: string | null;
}

/**
 * Quality grade at or above which a recall is considered successful.
 * Grades 0-2 are treated as failures (repetitions reset); grades 3-5 are passes.
 * Exported for use by downstream consumers (e.g., scoring/grading modules).
 */
export const QUALITY_PASS_THRESHOLD = 3;

