  1→/**
  2→ * SM-2 review state for a single card.
  3→ * Tracks the easiness factor, current interval in days, and number of consecutive correct repetitions.
  4→ */
  5→export interface SM2State {
  6→	/** Easiness factor (EF), always >= 1.3. Higher values mean the card is easier to recall. */
  7→	readonly easinessFactor: number;
  8→	/** Current inter-repetition interval in days. 0 means unreviewed; >= 1 after any review. */
  9→	readonly interval: number;
 10→	/** Number of consecutive correct (quality >= 3) repetitions. Resets to 0 on failure. */
 11→	readonly repetitions: number;
 12→}
 13→
 14→/**
 15→ * Result of an SM-2 calculation, including the updated state and the next scheduled review date.
 16→ */
 17→export interface SM2Result {
 18→	/** The updated SM-2 state after the review. */
 19→	readonly state: SM2State;
 20→	/** Next review date as a YYYY-MM-DD string, or null for the pre-first-review state. */
 21→	readonly nextReviewDate: string | null;
 22→}
 23→
 24→const DEFAULT_EASINESS_FACTOR = 2.5;
 25→const MIN_EASINESS_FACTOR = 1.3;
 26→const INITIAL_INTERVAL_FIRST = 1;
 27→const INITIAL_INTERVAL_SECOND = 6;
 28→
 29→/**
 30→ * Quality grade at or above which a recall is considered successful.
 31→ * Grades 0-2 are treated as failures (repetitions reset); grades 3-5 are passes.
 32→ * Exported for use by downstream consumers (e.g., scoring/grading modules).
 33→ */
 34→export const QUALITY_PASS_THRESHOLD = 3;
 35→
 36→/**
 37→ * Returns the default SM-2 state for a new/unreviewed card.
 38→ * EF starts at 2.5, interval at 0 (unreviewed), and repetitions at 0.
 39→ */
 40→export function getDefaultSM2State(): SM2State {
 41→	return {
 42→		easinessFactor: DEFAULT_EASINESS_FACTOR,
 43→		interval: 0,
 44→		repetitions: 0,
 45→	};
 46→}
 47→
 48→/**
 49→ * Core SM-2 algorithm: computes updated review state and next review date.
 50→ *
 51→ * @param state - Current SM-2 state of the card.
 52→ * @param quality - Recall quality grade, an integer from 0 (complete blackout) to 5 (perfect recall).
 53→ * @param today - Current date as a YYYY-MM-DD string.
 54→ * @returns Updated SM-2 result with new state and next scheduled review date.
 55→ * @throws If quality is not an integer in the range 0-5.
 56→ */
 57→export function calculateSM2(
 58→	state: SM2State,
 59→	quality: number,
 60→	today: string,
 61→): SM2Result {
 62→	if (!Number.isInteger(quality)) {
 63→		throw new Error(`Invalid quality: expected integer, got ${quality}`);
 64→	}
 65→	if (quality < 0 || quality > 5) {
 66→		throw new Error(`Invalid quality: expected 0-5, got ${quality}`);
 67→	}
 68→
 69→	let repetitions: number;
 70→	let interval: number;
 71→
 72→	if (quality >= QUALITY_PASS_THRESHOLD) {
 73→		if (state.repetitions === 0) {
 74→			interval = INITIAL_INTERVAL_FIRST;
 75→		} else if (state.repetitions === 1) {
 76→			interval = INITIAL_INTERVAL_SECOND;
 77→		} else {
 78→			interval = Math.round(state.interval * state.easinessFactor);
 79→		}
 80→		repetitions = state.repetitions + 1;
 81→	} else {
 82→		repetitions = 0;
 83→		interval = INITIAL_INTERVAL_FIRST;
 84→	}
 85→
 86→	const ef = Math.max(
 87→		state.easinessFactor +
 88→			(0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
 89→		MIN_EASINESS_FACTOR,
 90→	);
 91→
 92→	const nextReviewDate = addDays(today, interval);
 93→
 94→	return {
 95→		state: { easinessFactor: ef, interval, repetitions },
 96→		nextReviewDate,
 97→	};
 98→}
 99→
100→/**
101→ * Determines if a card is due for review.
102→ *
103→ * @param nextReviewDate - The card's next review date as YYYY-MM-DD, or null for new/unreviewed cards.
104→ * @param today - Current date as a YYYY-MM-DD string.
105→ * @returns True if the card should be reviewed today (null, past, or today's date); false if future.
106→ */
107→export function isDue(nextReviewDate: string | null, today: string): boolean {
108→	if (nextReviewDate === null) {
109→		return true;
110→	}
111→	return today >= nextReviewDate;
112→}
113→
114→/**
115→ * Formats a Date object as a YYYY-MM-DD string using UTC components.
116→ *
117→ * @param date - The Date object to format.
118→ * @returns Date string in YYYY-MM-DD format.
119→ */
120→export function formatDateAsISO(date: Date): string {
121→	return date.toISOString().slice(0, 10);
122→}
123→
124→/**
125→ * Adds a number of days to a YYYY-MM-DD date string, returning a new YYYY-MM-DD string.
126→ *
127→ * @param dateStr - Starting date in YYYY-MM-DD format.
128→ * @param days - Non-negative integer number of days to add.
129→ * @returns New date string in YYYY-MM-DD format.
130→ * @throws If days is negative or dateStr does not match YYYY-MM-DD format.
131→ */
132→export function addDays(dateStr: string, days: number): string {
133→	if (days < 0) {
134→		throw new Error(`Invalid days: expected non-negative integer, got ${days}`);
135→	}
136→	if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
137→		throw new Error(`Invalid date format: expected YYYY-MM-DD, got ${dateStr}`);
138→	}
139→	const date = new Date(`${dateStr}T00:00:00Z`);
140→	date.setUTCDate(date.getUTCDate() + days);
141→	return formatDateAsISO(date);
142→}
