281→			let state: SM2State = getDefaultSM2State();
282→			const seqLen = Math.floor(rng2() * 20) + 1;
283→			for (let j = 0; j < seqLen; j++) {
284→				const quality = Math.floor(rng2() * 6);
285→				const result = calculateSM2(state, quality, today);
286→				expect(result.state.interval).toBeGreaterThanOrEqual(1);
287→				state = result.state;
288→			}
289→		}
290→	});
291→
292→	it("repetitions is non-negative after any review", () => {
293→		const rng3 = seededRng(999);
294→		for (let i = 0; i < 120; i++) {
295→			let state: SM2State = getDefaultSM2State();
296→			const seqLen = Math.floor(rng3() * 20) + 1;
297→			for (let j = 0; j < seqLen; j++) {
298→				const quality = Math.floor(rng3() * 6);
299→				const result = calculateSM2(state, quality, today);
300→				expect(result.state.repetitions).toBeGreaterThanOrEqual(0);
301→				state = result.state;
302→			}
303→		}
304→	});
305→
306→	it("intervals are non-decreasing for consecutive reviews with any constant quality >= 3", () => {
307→		for (const quality of [3, 4, 5]) {
308→			let state: SM2State = getDefaultSM2State();
309→			let prevInterval = 0;
310→			// Use a fixed date for each step to avoid date overflow with large intervals
311→			for (let j = 0; j < 15; j++) {
312→				const result = calculateSM2(state, quality, today);
313→				expect(result.state.interval).toBeGreaterThanOrEqual(prevInterval);
314→				prevInterval = result.state.interval;
315→				state = result.state;
316→			}
317→		}
318→	});
319→
320→	it("computes correct nextReviewDate", () => {
321→		const rng4 = seededRng(777);
322→		for (let i = 0; i < 120; i++) {
323→			const state: SM2State = getDefaultSM2State();
324→			const quality = Math.floor(rng4() * 6);
325→			const result = calculateSM2(state, quality, today);
326→			const expected = addDays(today, result.state.interval);
327→			expect(result.nextReviewDate).toBe(expected);
328→		}
329→	});
330→});
331→
332→describe("isDue", () => {
333→	it("returns true for null nextReviewDate", () => {
334→		expect(isDue(null, "2026-04-04")).toBe(true);
335→	});
336→
337→	it("returns true for past date", () => {
338→		expect(isDue("2026-04-01", "2026-04-04")).toBe(true);
339→	});
340→
341→	it("returns true for today's date", () => {
342→		expect(isDue("2026-04-04", "2026-04-04")).toBe(true);
343→	});
344→
345→	it("returns false for future date", () => {
346→		expect(isDue("2026-04-10", "2026-04-04")).toBe(false);
347→	});
348→});
349→
350→describe("calculateSM2 — end-to-end lifecycle", () => {
351→	it("full lifecycle: new card through 5 reviews with varying quality", () => {
352→		let state: SM2State = getDefaultSM2State();
353→		let currentDate = "2026-04-04";
354→
355→		// Review 1: quality 4 (pass)
356→		let result = calculateSM2(state, 4, currentDate);
357→		expect(result.state.repetitions).toBe(1);
358→		expect(result.state.interval).toBe(1);
359→		expect(result.state.easinessFactor).toBe(2.5);
360→		state = result.state;
361→		currentDate = result.nextReviewDate as string;
362→
363→		// Review 2: quality 5 (strong pass)
364→		result = calculateSM2(state, 5, currentDate);
365→		expect(result.state.repetitions).toBe(2);
366→		expect(result.state.interval).toBe(6);
367→		expect(result.state.easinessFactor).toBeCloseTo(2.6, 10);
368→		state = result.state;
369→		currentDate = result.nextReviewDate as string;
370→
371→		// Review 3: quality 2 (fail — resets)
372→		result = calculateSM2(state, 2, currentDate);
373→		expect(result.state.repetitions).toBe(0);
374→		expect(result.state.interval).toBe(1);
375→		// EF updated even on failure: 2.6 + (0.1 - 3*(0.08+3*0.02)) = 2.6 - 0.32 = 2.28
376→		expect(result.state.easinessFactor).toBeCloseTo(2.28, 2);
377→		state = result.state;
378→		currentDate = result.nextReviewDate as string;
379→
380→		// Review 4: quality 3 (pass, barely)
381→		result = calculateSM2(state, 3, currentDate);
382→		expect(result.state.repetitions).toBe(1);
383→		expect(result.state.interval).toBe(1);
384→		// EF: 2.28 + (0.1 - 2*(0.08+2*0.02)) = 2.28 - 0.14 = 2.14
385→		expect(result.state.easinessFactor).toBeCloseTo(2.14, 2);
386→		state = result.state;
387→		currentDate = result.nextReviewDate as string;
388→
389→		// Review 5: quality 4 (pass, continues)
390→		result = calculateSM2(state, 4, currentDate);
391→		expect(result.state.repetitions).toBe(2);
392→		expect(result.state.interval).toBe(6);
393→		// EF: 2.14 + 0 = 2.14
394→		expect(result.state.easinessFactor).toBeCloseTo(2.14, 2);
395→		state = result.state;
396→
397→		// Verify the final nextReviewDate is 6 days from the last review
398→		expect(result.nextReviewDate).toBe(addDays(currentDate, 6));
399→	});
400→});
