 1→/** Score summary for a completed quiz session. */
 2→export interface ScoreSummary {
 3→  readonly total: number;
 4→  readonly correct: number;
 5→  readonly incorrect: number;
 6→  readonly percentage: number;
 7→}
 8→
 9→/** Calculate score from a map of card ID -> correct/incorrect. */
10→export function calculateScore(answers: Map<string, boolean>): ScoreSummary {
11→  let correct = 0;
12→  let incorrect = 0;
13→  for (const [, isCorrect] of answers) {
14→    if (isCorrect) {
15→      correct++;
16→    } else {
17→      incorrect++;
18→    }
19→  }
20→  const total = correct + incorrect;
21→  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
22→  return { total, correct, incorrect, percentage };
23→}
24→
25→/** Format a score summary as a human-readable string. */
26→export function formatScore(summary: ScoreSummary): string {
27→  return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
28→}
