34→		const input = validateInput(completeEpicInputSchema, args, stdin);
35→
36→		const projectDir = resolveProjectDir();
37→		const result = await complete(
38→			projectDir,
39→			{ type: "epic", name: input.epic },
40→			{ type: "epic", verificationResults: input.verificationResults },
