 3→
 4→describe("createCard", () => {
 5→  it("should create a card with front and back", () => {
 6→    const card = createCard("Q", "A");
 7→    expect(card.front).toBe("Q");
 8→    expect(card.back).toBe("A");
 9→    expect(card.id).toBeDefined();
10→    expect(card.tags).toEqual([]);
11→    expect(card.createdAt).toBeDefined();
12→  });
13→
14→  it("should accept tags", () => {
15→    const card = createCard("Q", "A", ["math", "algebra"]);
16→    expect(card.tags).toEqual(["math", "algebra"]);
17→  });
18→});
