// ─── Phase 1: Types ───

export type DateString = string & { readonly __brand: "DateString" };

export type ReviewRating = 0 | 1 | 2 | 3 | 4 | 5;

export interface SM2State {
  readonly easinessFactor: number;
  readonly repetitionCount: number;
  readonly interval: number;
  readonly nextReviewDate: DateString | null;
  readonly lastReviewDate: DateString | null;
}

const DEFAULT_EASINESS_FACTOR = 2.5;
const MINIMUM_EASINESS_FACTOR = 1.3;

// ─── Phase 2: Core Functions ───

/**
 * Converts a Date object to a DateString in YYYY-MM-DD format using UTC methods.
 */
export function toDateString(date: Date): DateString {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}` as DateString;
}

/**
 * Returns today's date as a DateString (UTC).
 */
export function today(): DateString {
  return toDateString(new Date());
}

/**
 * Parses a YYYY-MM-DD DateString as UTC, adds the given number of days,
 * and returns the resulting DateString.
 */
function addDays(date: DateString, days: number): DateString {
  const [y, m, d] = date.split("-").map(Number);
  const result = new Date(Date.UTC(y, m - 1, d));
  result.setUTCDate(result.getUTCDate() + days);
  return toDateString(result);
}

/**
 * Creates the default initial SM-2 state.
 */
export function createInitialSM2State(): SM2State {
  return {
    easinessFactor: DEFAULT_EASINESS_FACTOR,
    repetitionCount: 0,
    interval: 0,
    nextReviewDate: null,
    lastReviewDate: null,
  };
}

/**
 * Core SM-2 algorithm implementation.
 *
 * Note: this implementation updates EF on every review (including failures)
 * and uses the post-update EF for interval calculation.
 */
export function calculateSM2(
  state: SM2State,
  quality: ReviewRating,
  reviewDate?: DateString,
): SM2State {
  const rd: DateString = reviewDate ?? today();

  // Update easiness factor (applied on every review, including failures)
  const newEF = Math.max(
    MINIMUM_EASINESS_FACTOR,
    state.easinessFactor +
      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
  );

  let newInterval: number;
  let newRepetitionCount: number;

  if (quality >= 3) {
    // Successful recall
    if (state.repetitionCount === 0) {
      newInterval = 1;
    } else if (state.repetitionCount === 1) {
      newInterval = 6;
    } else {
      newInterval = Math.round(state.interval * newEF);
    }
    newRepetitionCount = state.repetitionCount + 1;
  } else {
    // Failed recall – reset
    newInterval = 1;
    newRepetitionCount = 0;
  }

  const nextReviewDate = addDays(rd, newInterval);

  return {
    easinessFactor: newEF,
    repetitionCount: newRepetitionCount,
    interval: newInterval,
    nextReviewDate,
    lastReviewDate: rd,
  };
}

/**
 * Returns true if the card is due for review: either it has never been reviewed
 * (nextReviewDate is null) or its nextReviewDate is on or before the given date.
 */
export function isDue(state: SM2State, now?: DateString): boolean {
  if (state.nextReviewDate === null) {
    return true;
  }
  const currentDate = now ?? today();
  return state.nextReviewDate <= currentDate;
}

