import { describe, it, expect } from "bun:test";
import {
  toDateString,
  createInitialSM2State,
  calculateSM2,
  isDue,
  type DateString,
  type SM2State,
} from "../src/sm2";

// Helper to create a DateString literal without going through toDateString
function ds(s: string): DateString {
  return s as DateString;
}

describe("toDateString", () => {
  it("formats a date as YYYY-MM-DD", () => {
    const date = new Date(Date.UTC(2026, 3, 4)); // April 4, 2026
    expect(toDateString(date)).toBe("2026-04-04");
  });

  it("zero-pads single-digit months and days", () => {
    const date = new Date(Date.UTC(2025, 0, 5)); // January 5, 2025
    expect(toDateString(date)).toBe("2025-01-05");
  });
});

describe("createInitialSM2State", () => {
  it("returns default values (EF=2.5, n=0, interval=0, null dates)", () => {
    const state = createInitialSM2State();
    expect(state.easinessFactor).toBeCloseTo(2.5, 2);
    expect(state.repetitionCount).toBe(0);
    expect(state.interval).toBe(0);
    expect(state.nextReviewDate).toBeNull();
    expect(state.lastReviewDate).toBeNull();
  });
});

describe("calculateSM2", () => {
  const reviewDate = ds("2026-04-04");

  describe("successful recall (quality >= 3)", () => {
    it("first review (n=0, q=4): interval=1, n=1, EF unchanged", () => {
      const state = createInitialSM2State();
      const result = calculateSM2(state, 4, reviewDate);
      expect(result.easinessFactor).toBeCloseTo(2.5, 2);
      expect(result.repetitionCount).toBe(1);
      expect(result.interval).toBe(1);
    });

    it("first review (n=0, q=5): interval=1, n=1, EF increases by 0.1", () => {
      const state = createInitialSM2State();
      const result = calculateSM2(state, 5, reviewDate);
      expect(result.easinessFactor).toBeCloseTo(2.6, 2);
      expect(result.repetitionCount).toBe(1);
      expect(result.interval).toBe(1);
    });

    it("first review (n=0, q=3): interval=1, n=1, EF decreases by 0.14", () => {
      const state = createInitialSM2State();
      const result = calculateSM2(state, 3, reviewDate);
      expect(result.easinessFactor).toBeCloseTo(2.36, 2);
      expect(result.repetitionCount).toBe(1);
      expect(result.interval).toBe(1);
    });

    it("second review (n=1, q=5): interval=6, n=2", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 1,
        interval: 1,
        nextReviewDate: ds("2026-04-05"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 5, ds("2026-04-05"));
      expect(result.easinessFactor).toBeCloseTo(2.6, 2);
      expect(result.repetitionCount).toBe(2);
      expect(result.interval).toBe(6);
    });

    it("third review (n=2, interval=6, EF=2.5, q=5): interval=round(6*2.6)=16, n=3", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 5, ds("2026-04-10"));
      // EF updates first: 2.5 + 0.1 = 2.6, then interval = round(6 * 2.6) = 16
      expect(result.easinessFactor).toBeCloseTo(2.6, 2);
      expect(result.repetitionCount).toBe(3);
      expect(result.interval).toBe(16);
    });

    it("uses custom reviewDate instead of today", () => {
      const state = createInitialSM2State();
      const customDate = ds("2030-12-25");
      const result = calculateSM2(state, 4, customDate);
      expect(result.lastReviewDate).toBe("2030-12-25");
      expect(result.nextReviewDate).toBe("2030-12-26");
    });

    it("sets lastReviewDate to the review date", () => {
      const state = createInitialSM2State();
      const result = calculateSM2(state, 4, reviewDate);
      expect(result.lastReviewDate).toBe("2026-04-04");
    });

    it("sets nextReviewDate to reviewDate + interval days", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 1,
        interval: 1,
        nextReviewDate: ds("2026-04-05"),
        lastReviewDate: ds("2026-04-04"),
      };
      // n=1 -> interval=6, so next = 2026-04-05 + 6 = 2026-04-11
      const result = calculateSM2(state, 4, ds("2026-04-05"));
      expect(result.nextReviewDate).toBe("2026-04-11");
    });
  });

  describe("failed recall (quality < 3)", () => {
    it("quality=2 resets n to 0 and interval to 1", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 3,
        interval: 15,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-01"),
      };
      const result = calculateSM2(state, 2, reviewDate);
      expect(result.repetitionCount).toBe(0);
      expect(result.interval).toBe(1);
    });

    it("quality=1 resets n to 0 and interval to 1", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 3,
        interval: 15,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-01"),
      };
      const result = calculateSM2(state, 1, reviewDate);
      expect(result.repetitionCount).toBe(0);
      expect(result.interval).toBe(1);
    });

    it("quality=0 resets n to 0 and interval to 1", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 3,
        interval: 15,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-01"),
      };
      const result = calculateSM2(state, 0, reviewDate);
      expect(result.repetitionCount).toBe(0);
      expect(result.interval).toBe(1);
    });

    it("EF still updates on failure (decreases)", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 3,
        interval: 15,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-01"),
      };
      const result = calculateSM2(state, 2, reviewDate);
      // EF delta for q=2: 0.1 - (3)*(0.08 + 3*0.02) = 0.1 - 0.42 = -0.32
      expect(result.easinessFactor).toBeCloseTo(2.18, 2);
    });

    it("failed card after multiple successes resets to n=0, interval=1", () => {
      const state: SM2State = {
        easinessFactor: 2.6,
        repetitionCount: 5,
        interval: 100,
        nextReviewDate: ds("2026-07-01"),
        lastReviewDate: ds("2026-03-23"),
      };
      const result = calculateSM2(state, 1, reviewDate);
      expect(result.repetitionCount).toBe(0);
      expect(result.interval).toBe(1);
    });
  });

  describe("easiness factor edge cases", () => {
    it("EF does not drop below 1.3 after repeated q=0 ratings", () => {
      let state = createInitialSM2State();
      // Apply q=0 many times
      for (let i = 0; i < 20; i++) {
        state = calculateSM2(state, 0, reviewDate);
      }
      expect(state.easinessFactor).toBeCloseTo(1.3, 2);
    });

    it("EF increases by exactly 0.1 when q=5", () => {
      const state: SM2State = {
        easinessFactor: 2.0,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 5, reviewDate);
      expect(result.easinessFactor).toBeCloseTo(2.1, 2);
    });

    it("EF stays the same when q=4 (delta is 0)", () => {
      const state: SM2State = {
        easinessFactor: 2.0,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 4, reviewDate);
      expect(result.easinessFactor).toBeCloseTo(2.0, 2);
    });

    it("EF decreases when q=3", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 3, reviewDate);
      // delta for q=3: 0.1 - 2*(0.08 + 2*0.02) = 0.1 - 0.24 = -0.14
      expect(result.easinessFactor).toBeCloseTo(2.36, 2);
    });

    it("EF decreases more steeply for lower quality ratings", () => {
      const baseState: SM2State = {
        easinessFactor: 2.5,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const resultQ2 = calculateSM2(baseState, 2, reviewDate);
      const resultQ1 = calculateSM2(baseState, 1, reviewDate);
      const resultQ0 = calculateSM2(baseState, 0, reviewDate);

      // q=2 delta: 0.1 - 3*(0.08+3*0.02) = -0.32 -> EF=2.18
      // q=1 delta: 0.1 - 4*(0.08+4*0.02) = -0.54 -> EF=1.96
      // q=0 delta: 0.1 - 5*(0.08+5*0.02) = -0.80 -> EF=1.70
      expect(resultQ2.easinessFactor).toBeCloseTo(2.18, 2);
      expect(resultQ1.easinessFactor).toBeCloseTo(1.96, 2);
      expect(resultQ0.easinessFactor).toBeCloseTo(1.70, 2);
      expect(resultQ0.easinessFactor).toBeLessThan(resultQ1.easinessFactor);
      expect(resultQ1.easinessFactor).toBeLessThan(resultQ2.easinessFactor);
    });

    it("EF clamps to 1.3 when q=3 and EF is near minimum (e.g., EF=1.32)", () => {
      const state: SM2State = {
        easinessFactor: 1.32,
        repetitionCount: 2,
        interval: 6,
        nextReviewDate: ds("2026-04-10"),
        lastReviewDate: ds("2026-04-04"),
      };
      const result = calculateSM2(state, 3, reviewDate);
      // 1.32 + (-0.14) = 1.18, clamped to 1.3
      expect(result.easinessFactor).toBeCloseTo(1.3, 2);
    });
  });

  describe("multi-step sequences (known-answer tests)", () => {
    it("sequence: new card -> q=4 -> q=5 -> q=5 -> q=5 produces expected state at each step", () => {
      let state = createInitialSM2State();
      let date = ds("2026-01-01");

      // Step 1: q=4
      state = calculateSM2(state, 4, date);
      expect(state.easinessFactor).toBeCloseTo(2.5, 2);
      expect(state.repetitionCount).toBe(1);
      expect(state.interval).toBe(1);

      // Step 2: q=5 (review next day)
      date = ds("2026-01-02");
      state = calculateSM2(state, 5, date);
      expect(state.easinessFactor).toBeCloseTo(2.6, 2);
      expect(state.repetitionCount).toBe(2);
      expect(state.interval).toBe(6);

      // Step 3: q=5 (review after 6 days)
      date = ds("2026-01-08");
      state = calculateSM2(state, 5, date);
      // EF: 2.6 + 0.1 = 2.7, interval = round(6 * 2.7) = 16
      expect(state.easinessFactor).toBeCloseTo(2.7, 2);
      expect(state.repetitionCount).toBe(3);
      expect(state.interval).toBe(16);

      // Step 4: q=5
      date = ds("2026-01-24");
      state = calculateSM2(state, 5, date);
      // EF: 2.7 + 0.1 = 2.8, interval = round(16 * 2.8) = 45
      expect(state.easinessFactor).toBeCloseTo(2.8, 2);
      expect(state.repetitionCount).toBe(4);
      expect(state.interval).toBe(45);
    });

    it("sequence: new card -> q=5 -> q=2 (fail) -> q=4 (restart) produces expected state at each step", () => {
      let state = createInitialSM2State();

      // Step 1: q=5
      state = calculateSM2(state, 5, ds("2026-01-01"));
      expect(state.easinessFactor).toBeCloseTo(2.6, 2);
      expect(state.repetitionCount).toBe(1);
      expect(state.interval).toBe(1);

      // Step 2: q=5
      state = calculateSM2(state, 5, ds("2026-01-02"));
      expect(state.easinessFactor).toBeCloseTo(2.7, 2);
      expect(state.repetitionCount).toBe(2);
      expect(state.interval).toBe(6);

      // Step 3: q=2 (fail)
      state = calculateSM2(state, 2, ds("2026-01-08"));
      // EF: 2.7 + (0.1 - 3*(0.08+3*0.02)) = 2.7 - 0.32 = 2.38
      expect(state.easinessFactor).toBeCloseTo(2.38, 2);
      expect(state.repetitionCount).toBe(0);
      expect(state.interval).toBe(1);

      // Step 4: q=4 (restart)
      state = calculateSM2(state, 4, ds("2026-01-09"));
      expect(state.easinessFactor).toBeCloseTo(2.38, 2);
      expect(state.repetitionCount).toBe(1);
      expect(state.interval).toBe(1);

      // Step 5: q=4
      state = calculateSM2(state, 4, ds("2026-01-10"));
      expect(state.easinessFactor).toBeCloseTo(2.38, 2);
      expect(state.repetitionCount).toBe(2);
      expect(state.interval).toBe(6);
    });
  });
});

describe("isDue", () => {
  it("returns true when nextReviewDate is null (new card)", () => {
    const state = createInitialSM2State();
    expect(isDue(state, ds("2026-04-04"))).toBe(true);
  });

  it("returns true when nextReviewDate is in the past", () => {
    const state: SM2State = {
      easinessFactor: 2.5,
      repetitionCount: 1,
      interval: 1,
      nextReviewDate: ds("2026-04-01"),
      lastReviewDate: ds("2026-03-31"),
    };
    expect(isDue(state, ds("2026-04-04"))).toBe(true);
  });

  it("returns true when nextReviewDate is today", () => {
    const state: SM2State = {
      easinessFactor: 2.5,
      repetitionCount: 1,
      interval: 1,
      nextReviewDate: ds("2026-04-04"),
      lastReviewDate: ds("2026-04-03"),
    };
    expect(isDue(state, ds("2026-04-04"))).toBe(true);
  });

  it("returns false when nextReviewDate is in the future", () => {
    const state: SM2State = {
      easinessFactor: 2.5,
      repetitionCount: 1,
      interval: 1,
      nextReviewDate: ds("2026-04-10"),
      lastReviewDate: ds("2026-04-04"),
    };
    expect(isDue(state, ds("2026-04-04"))).toBe(false);
  });
});

