 1→/** Represents a single flashcard with a front (question) and back (answer). */
 2→export interface Card {
 3→  readonly id: string;
 4→  readonly front: string;
 5→  readonly back: string;
 6→  readonly tags: readonly string[];
 7→  readonly createdAt: string;
 8→}
 9→
10→/** Load cards from a JSON file. */
11→export function loadCards(filePath: string): Card[] {
12→  const raw = Bun.file(filePath);
13→  // In a real app we'd validate, but this is the initial skeleton
14→  return [] as Card[];
15→}
16→
17→/** Create a new card with a generated ID. */
18→export function createCard(front: string, back: string, tags: string[] = []): Card {
19→  return {
20→    id: crypto.randomUUID(),
21→    front,
22→    back,
23→    tags,
24→    createdAt: new Date().toISOString(),
25→  };
26→}
27→

  1→// ─── Phase 1: Types ───
  2→
  3→export type DateString = string & { readonly __brand: "DateString" };
  4→
  5→export type ReviewRating = 0 | 1 | 2 | 3 | 4 | 5;
  6→
  7→export interface SM2State {
  8→  readonly easinessFactor: number;
  9→  readonly repetitionCount: number;
 10→  readonly interval: number;
 11→  readonly nextReviewDate: DateString | null;
 12→  readonly lastReviewDate: DateString | null;
 13→}
 14→
 15→const DEFAULT_EASINESS_FACTOR = 2.5;
 16→const MINIMUM_EASINESS_FACTOR = 1.3;
 17→
 18→// ─── Phase 2: Core Functions ───
 19→
 20→/**
 21→ * Converts a Date object to a DateString in YYYY-MM-DD format using UTC methods.
 22→ */
 23→export function toDateString(date: Date): DateString {
 24→  const y = date.getUTCFullYear();
 25→  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
 26→  const d = String(date.getUTCDate()).padStart(2, "0");
 27→  return `${y}-${m}-${d}` as DateString;
 28→}
 29→
 30→/**
 31→ * Returns today's date as a DateString (UTC).
 32→ */
 33→export function today(): DateString {
 34→  return toDateString(new Date());
 35→}
 36→
 37→/**
 38→ * Parses a YYYY-MM-DD DateString as UTC, adds the given number of days,
 39→ * and returns the resulting DateString.
 40→ */
 41→function addDays(date: DateString, days: number): DateString {
 42→  const [y, m, d] = date.split("-").map(Number);
 43→  const result = new Date(Date.UTC(y, m - 1, d));
 44→  result.setUTCDate(result.getUTCDate() + days);
 45→  return toDateString(result);
 46→}
 47→
 48→/**
 49→ * Creates the default initial SM-2 state.
 50→ */
 51→export function createInitialSM2State(): SM2State {
 52→  return {
 53→    easinessFactor: DEFAULT_EASINESS_FACTOR,
 54→    repetitionCount: 0,
 55→    interval: 0,
 56→    nextReviewDate: null,
 57→    lastReviewDate: null,
 58→  };
 59→}
 60→
 61→/**
 62→ * Core SM-2 algorithm implementation.
 63→ *
 64→ * Note: this implementation updates EF on every review (including failures)
 65→ * and uses the post-update EF for interval calculation.
 66→ */
 67→export function calculateSM2(
 68→  state: SM2State,
 69→  quality: ReviewRating,
 70→  reviewDate?: DateString,
 71→): SM2State {
 72→  const rd: DateString = reviewDate ?? today();
 73→
 74→  // Update easiness factor (applied on every review, including failures)
 75→  const newEF = Math.max(
 76→    MINIMUM_EASINESS_FACTOR,
 77→    state.easinessFactor +
 78→      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
 79→  );
 80→
 81→  let newInterval: number;
 82→  let newRepetitionCount: number;
 83→
 84→  if (quality >= 3) {
 85→    // Successful recall
 86→    if (state.repetitionCount === 0) {
 87→      newInterval = 1;
 88→    } else if (state.repetitionCount === 1) {
 89→      newInterval = 6;
 90→    } else {
 91→      newInterval = Math.round(state.interval * newEF);
 92→    }
 93→    newRepetitionCount = state.repetitionCount + 1;
 94→  } else {
 95→    // Failed recall – reset
 96→    newInterval = 1;
 97→    newRepetitionCount = 0;
 98→  }
 99→
100→  const nextReviewDate = addDays(rd, newInterval);
101→
102→  return {
103→    easinessFactor: newEF,
104→    repetitionCount: newRepetitionCount,
105→    interval: newInterval,
106→    nextReviewDate,
107→    lastReviewDate: rd,
108→  };
109→}
110→
111→/**
112→ * Returns true if the card is due for review: either it has never been reviewed
113→ * (nextReviewDate is null) or its nextReviewDate is on or before the given date.
114→ */
115→export function isDue(state: SM2State, now?: DateString): boolean {
116→  if (state.nextReviewDate === null) {
117→    return true;
118→  }
119→  const currentDate = now ?? today();
120→  return state.nextReviewDate <= currentDate;
121→}
122→

