 1→/** Represents a single flashcard with a front (question) and back (answer). */
 2→export interface Card {
 3→  readonly id: string;
 4→  readonly front: string;
 5→  readonly back: string;
 6→  readonly tags: readonly string[];
 7→  readonly createdAt: string;
 8→}
 9→
10→/** Load cards from a JSON file. */
11→export function loadCards(filePath: string): Card[] {
12→  const raw = Bun.file(filePath);
13→  // In a real app we'd validate, but this is the initial skeleton
14→  return [] as Card[];
15→}
16→
17→/** Create a new card with a generated ID. */
18→export function createCard(front: string, back: string, tags: string[] = []): Card {
19→  return {
20→    id: crypto.randomUUID(),
21→    front,
22→    back,
23→    tags,
24→    createdAt: new Date().toISOString(),
25→  };
26→}
27→

 1→import type { Card } from "./card";
 2→
 3→/** Quiz session state. */
 4→export interface QuizSession {
 5→  readonly cards: readonly Card[];
 6→  currentIndex: number;
 7→  readonly answers: Map<string, boolean>;
 8→}
 9→
10→/** Start a new quiz session with the given cards. */
11→export function startQuiz(cards: Card[]): QuizSession {
12→  return {
13→    cards,
14→    currentIndex: 0,
15→    answers: new Map(),
16→  };
17→}
18→
19→/** Get the current card in the quiz, or undefined if done. */
20→export function currentCard(session: QuizSession): Card | undefined {
21→  return session.cards[session.currentIndex];
22→}
23→
24→/** Record an answer and advance to the next card. */
25→export function answerCard(session: QuizSession, correct: boolean): void {
26→  const card = currentCard(session);
27→  if (card) {
28→    session.answers.set(card.id, correct);
29→    session.currentIndex++;
30→  }
31→}
32→
33→/** Check if the quiz is complete. */
34→export function isQuizComplete(session: QuizSession): boolean {
35→  return session.currentIndex >= session.cards.length;
36→}
37→

 1→/** Score summary for a completed quiz session. */
 2→export interface ScoreSummary {
 3→  readonly total: number;
 4→  readonly correct: number;
 5→  readonly incorrect: number;
 6→  readonly percentage: number;
 7→}
 8→
 9→/** Calculate score from a map of card ID -> correct/incorrect. */
10→export function calculateScore(answers: Map<string, boolean>): ScoreSummary {
11→  let correct = 0;
12→  let incorrect = 0;
13→  for (const [, isCorrect] of answers) {
14→    if (isCorrect) {
15→      correct++;
16→    } else {
17→      incorrect++;
18→    }
19→  }
20→  const total = correct + incorrect;
21→  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
22→  return { total, correct, incorrect, percentage };
23→}
24→
25→/** Format a score summary as a human-readable string. */
26→export function formatScore(summary: ScoreSummary): string {
27→  return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
28→}
29→

 1→import { createCard } from "./card";
 2→import { answerCard, currentCard, isQuizComplete, startQuiz } from "./quiz";
 3→import { calculateScore, formatScore } from "./score";
 4→
 5→/** Main CLI entry point. */
 6→function main(): void {
 7→  console.log("Flashcard CLI v0.1.0");
 8→
 9→  // Demo: create some cards and run a quick quiz
10→  const cards = [
11→    createCard("What is TypeScript?", "A typed superset of JavaScript"),
12→    createCard("What is Bun?", "A fast JavaScript runtime"),
13→    createCard("What is SM-2?", "A spaced repetition algorithm"),
14→  ];
15→
16→  const session = startQuiz(cards);
17→
18→  // Simulate answering all cards correctly
19→  while (!isQuizComplete(session)) {
20→    const card = currentCard(session);
21→    if (card) {
22→      console.log(`Q: ${card.front}`);
23→      console.log(`A: ${card.back}`);
24→      answerCard(session, true);
25→    }
26→  }
27→
28→  const score = calculateScore(session.answers);
29→  console.log(formatScore(score));
30→}
31→
32→main();
