### Types

```typescript
/**
 * SM-2 review state embedded in a card.
 *
 * Note: ReviewData's first three fields (easeFactor, interval, repetitions)
 * mirror Sm2State by design. This duplication is intentional — it keeps
 * card.ts free of imports from sm2.ts, enabling independent compilation and
 * testing. When constructing ReviewData from an Sm2Result, use the spread
 * pattern: `{ ...sm2Result.state, nextReviewDate, lastReviewDate }`.
 * If Sm2State gains new fields, ReviewData must be updated to match.
 */
export interface ReviewData {
  readonly easeFactor: number;
  readonly interval: number;
  readonly repetitions: number;
  readonly nextReviewDate: string;
  readonly lastReviewDate: string | null;
}

