 3→import { calculateScore, formatScore } from "./score";
 4→
 5→/** Main CLI entry point. */
 6→function main(): void {
 7→  console.log("Flashcard CLI v0.1.0");
 8→
 9→  // Demo: create some cards and run a quick quiz
10→  const cards = [
11→    createCard("What is TypeScript?", "A typed superset of JavaScript"),
12→    createCard("What is Bun?", "A fast JavaScript runtime"),
13→    createCard("What is SM-2?", "A spaced repetition algorithm"),
14→  ];
15→
16→  const session = startQuiz(cards);
17→
18→  // Simulate answering all cards correctly
19→  while (!isQuizComplete(session)) {
20→    const card = currentCard(session);
21→    if (card) {
22→      console.log(`Q: ${card.front}`);
23→      console.log(`A: ${card.back}`);
24→      answerCard(session, true);
25→    }
26→  }
27→
28→  const score = calculateScore(session.answers);
29→  console.log(formatScore(score));
30→}
31→
