/** Represents the current SM-2 state for a single card. */
export interface Sm2State {
  readonly easeFactor: number;
  readonly interval: number;
  readonly repetitions: number;
}

/** Result of an SM-2 calculation, containing the updated state and next review date. */
export interface Sm2Result {
  readonly state: Sm2State;
  readonly nextReviewDate: string;
}

/**
 * Creates the default initial SM-2 state for a new card.
 * @returns Default state with easeFactor 2.5, interval 0, repetitions 0.
 */
export function createDefaultSm2State(): Sm2State {
  return { easeFactor: 2.5, interval: 0, repetitions: 0 };
}

/**
 * Implements the SM-2 spaced repetition algorithm.
 *
 * Given the current review state and a quality rating (0-5), calculates
 * the updated state (ease factor, interval, repetitions) and the next review date.
 *
 * @param state - Current SM-2 state for the card.
 * @param quality - Quality of recall, integer in [0, 5].
 * @returns The updated SM-2 state and next review date as ISO 8601 string.
 * @throws {Error} If quality is not an integer in [0, 5].
 */
export function calculateSm2(state: Sm2State, quality: number): Sm2Result {
  if (
    typeof quality !== "number" ||
    !Number.isInteger(quality) ||
    quality < 0 ||
    quality > 5
  ) {
    throw new Error(
      `Invalid quality rating: ${quality}. Must be an integer between 0 and 5.`,
    );
  }

  let newInterval: number;
  let newRepetitions: number;

  if (quality >= 3) {
    if (state.repetitions === 0) {
      newInterval = 1;
    } else if (state.repetitions === 1) {
      newInterval = 6;
    } else {
      newInterval = Math.round(state.interval * state.easeFactor);
    }
    newRepetitions = state.repetitions + 1;
  } else {
    newInterval = 1;
    newRepetitions = 0;
  }

  const newEF = Math.max(
    1.3,
    state.easeFactor +
      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
  );

  const now = new Date();
  now.setDate(now.getDate() + newInterval);
  const nextReviewDate = now.toISOString();

  return {
    state: {
      easeFactor: newEF,
      interval: newInterval,
      repetitions: newRepetitions,
    },
    nextReviewDate,
  };
}

/**
 * Maps a user-facing 1-4 rating to the SM-2 internal 0-5 quality scale.
 *
 * @param rating - User rating: 1 (Again), 2 (Hard), 3 (Good), 4 (Easy).
 * @returns SM-2 quality value: 1->0, 2->2, 3->4, 4->5.
 */
export function mapUserRating(rating: 1 | 2 | 3 | 4): 0 | 2 | 4 | 5 {
  const mapping: Record<1 | 2 | 3 | 4, 0 | 2 | 4 | 5> = {
    1: 0,
    2: 2,
    3: 4,
    4: 5,
  };
  return mapping[rating];
}

import { describe, expect, test } from "bun:test";
import {
  calculateSm2,
  createDefaultSm2State,
  mapUserRating,
  type Sm2State,
} from "../src/sm2";

describe("createDefaultSm2State", () => {
  test("returns default state with EF 2.5, interval 0, repetitions 0", () => {
    const state = createDefaultSm2State();
    expect(state).toEqual({ easeFactor: 2.5, interval: 0, repetitions: 0 });
  });
});

describe("calculateSm2", () => {
  describe("successful recall progression", () => {
    test("quality 4 on default state yields interval 1, rep 1", () => {
      const state = createDefaultSm2State();
      const result = calculateSm2(state, 4);
      expect(result.state.interval).toBe(1);
      expect(result.state.repetitions).toBe(1);
      // EF unchanged for quality 4 (delta = 0.00)
      expect(result.state.easeFactor).toBeCloseTo(2.5, 5);
    });

    test("second review with quality 4 yields interval 6, rep 2", () => {
      const first = calculateSm2(createDefaultSm2State(), 4);
      const result = calculateSm2(first.state, 4);
      expect(result.state.interval).toBe(6);
      expect(result.state.repetitions).toBe(2);
      expect(result.state.easeFactor).toBeCloseTo(2.5, 5);
    });

    test("third review with quality 4 yields Math.round(6 * EF), rep 3", () => {
      const first = calculateSm2(createDefaultSm2State(), 4);
      const second = calculateSm2(first.state, 4);
      const result = calculateSm2(second.state, 4);
      expect(result.state.interval).toBe(Math.round(6 * 2.5)); // 15
      expect(result.state.repetitions).toBe(3);
    });
  });

  describe("failed recall", () => {
    test("quality 0 resets interval to 1 and repetitions to 0", () => {
      const progressed: Sm2State = {
        easeFactor: 2.5,
        interval: 15,
        repetitions: 3,
      };
      const result = calculateSm2(progressed, 0);
      expect(result.state.interval).toBe(1);
      expect(result.state.repetitions).toBe(0);
    });

    test("quality 1 resets interval to 1 and repetitions to 0", () => {
      const progressed: Sm2State = {
        easeFactor: 2.5,
        interval: 15,
        repetitions: 3,
      };
      const result = calculateSm2(progressed, 1);
      expect(result.state.interval).toBe(1);
      expect(result.state.repetitions).toBe(0);
    });

    test("quality 2 resets interval to 1 and repetitions to 0", () => {
      const progressed: Sm2State = {
        easeFactor: 2.5,
        interval: 15,
        repetitions: 3,
      };
      const result = calculateSm2(progressed, 2);
      expect(result.state.interval).toBe(1);
      expect(result.state.repetitions).toBe(0);
    });
  });

  describe("EF floor", () => {
    test("EF does not drop below 1.3 even after repeated failures", () => {
      const lowEF: Sm2State = {
        easeFactor: 1.3,
        interval: 1,
        repetitions: 0,
      };
      const result = calculateSm2(lowEF, 0);
      expect(result.state.easeFactor).toBe(1.3);
    });
  });

  describe("EF delta table", () => {
    const expectedDeltas: [number, number][] = [
      [0, -0.8],
      [1, -0.54],
      [2, -0.32],
      [3, -0.14],
      [4, 0.0],
      [5, 0.1],
    ];

    for (const [quality, expectedDelta] of expectedDeltas) {
      test(`quality ${quality} changes EF by ${expectedDelta}`, () => {
        const state: Sm2State = {
          easeFactor: 2.5,
          interval: 10,
          repetitions: 3,
        };
        const result = calculateSm2(state, quality);
        const actualDelta = result.state.easeFactor - 2.5;
        expect(actualDelta).toBeCloseTo(expectedDelta, 10);
      });
    }
  });

  describe("nextReviewDate", () => {
    test("returns a valid ISO 8601 date string", () => {
      const result = calculateSm2(createDefaultSm2State(), 4);
      expect(() => new Date(result.nextReviewDate)).not.toThrow();
      expect(new Date(result.nextReviewDate).toISOString()).toBe(
        result.nextReviewDate,
      );
    });
  });

  describe("quality validation", () => {
    test("throws for non-integer quality (2.5)", () => {
      expect(() => calculateSm2(createDefaultSm2State(), 2.5)).toThrow();
    });

    test("throws for quality below range (-1)", () => {
      expect(() => calculateSm2(createDefaultSm2State(), -1)).toThrow();
    });

    test("throws for quality above range (6)", () => {
      expect(() => calculateSm2(createDefaultSm2State(), 6)).toThrow();
    });

    test("throws for non-number values", () => {
      expect(() =>
        calculateSm2(createDefaultSm2State(), "3" as unknown as number),
      ).toThrow();
    });
  });
});

describe("mapUserRating", () => {
  test("maps 1 to 0 (Again)", () => {
    expect(mapUserRating(1)).toBe(0);
  });

  test("maps 2 to 2 (Hard)", () => {
    expect(mapUserRating(2)).toBe(2);
  });

  test("maps 3 to 4 (Good)", () => {
    expect(mapUserRating(3)).toBe(4);
  });

  test("maps 4 to 5 (Easy)", () => {
    expect(mapUserRating(4)).toBe(5);
  });
});

