/** Represents the spaced-repetition review state for a card. */
export interface ReviewData {
  readonly easeFactor: number;
  readonly interval: number;
  readonly repetitions: number;
  readonly nextReviewDate: string;
  readonly lastReviewDate: string | null;
}

/** Represents a single flashcard with a front (question) and back (answer). */
export interface Card {
  readonly id: string;
  readonly front: string;
  readonly back: string;
  readonly tags: readonly string[];
  readonly createdAt: string;
  readonly reviewData?: ReviewData;
}

/**
 * Load cards from a JSON file.
 *
 * Returns an empty array if the file does not exist.
 * Throws a descriptive error if the file contains malformed JSON.
 *
 * @param filePath - Path to the JSON file containing cards.
 * @returns The parsed array of cards.
 */
export async function loadCards(filePath: string): Promise<Card[]> {
  const file = Bun.file(filePath);
  if (!(await file.exists())) {
    return [];
  }
  const text = await file.text();
  try {
    return JSON.parse(text);
  } catch (err) {
    if (err instanceof SyntaxError) {
      throw new Error(`Failed to parse cards file: ${filePath}`);
    }
    throw err;
  }
}

/**
 * Save cards to a JSON file with 2-space indentation.
 *
 * @param filePath - Path to write the JSON file.
 * @param cards - The cards to persist.
 */
export async function saveCards(
  filePath: string,
  cards: readonly Card[],
): Promise<void> {
  const json = JSON.stringify(cards, null, 2);
  await Bun.write(filePath, json);
}

/** Create a new card with a generated ID. */
export function createCard(front: string, back: string, tags: string[] = []): Card {
  return {
    id: crypto.randomUUID(),
    front,
    back,
    tags,
    createdAt: new Date().toISOString(),
  };
}

import { describe, expect, it } from "bun:test";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createCard, loadCards, saveCards, type Card, type ReviewData } from "../src/card";

describe("createCard", () => {
  it("should create a card with front and back", () => {
    const card = createCard("Q", "A");
    expect(card.front).toBe("Q");
    expect(card.back).toBe("A");
    expect(card.id).toBeDefined();
    expect(card.tags).toEqual([]);
    expect(card.createdAt).toBeDefined();
  });

  it("should accept tags", () => {
    const card = createCard("Q", "A", ["math", "algebra"]);
    expect(card.tags).toEqual(["math", "algebra"]);
  });
});

function tempPath(): string {
  return join(tmpdir(), `flashcard-test-${crypto.randomUUID()}.json`);
}

describe("loadCards", () => {
  it("reads a valid JSON file containing cards with reviewData", async () => {
    const filePath = tempPath();
    const reviewData: ReviewData = {
      easeFactor: 2.5,
      interval: 6,
      repetitions: 2,
      nextReviewDate: "2026-04-10T00:00:00.000Z",
      lastReviewDate: "2026-04-04T00:00:00.000Z",
    };
    const cards: Card[] = [
      {
        id: "abc-123",
        front: "What is 2+2?",
        back: "4",
        tags: ["math"],
        createdAt: "2026-04-01T00:00:00.000Z",
        reviewData,
      },
    ];
    await Bun.write(filePath, JSON.stringify(cards, null, 2));

    const loaded = await loadCards(filePath);
    expect(loaded).toEqual(cards);
    expect(loaded[0].reviewData).toEqual(reviewData);
  });

  it("returns [] for a non-existent file path", async () => {
    const filePath = tempPath();
    const result = await loadCards(filePath);
    expect(result).toEqual([]);
  });

  it("throws with descriptive message for malformed JSON", async () => {
    const filePath = tempPath();
    await Bun.write(filePath, "{not valid json!!!");

    expect(loadCards(filePath)).rejects.toThrow(
      `Failed to parse cards file: ${filePath}`,
    );
  });
});

describe("saveCards", () => {
  it("writes JSON to disk with 2-space indentation", async () => {
    const filePath = tempPath();
    const cards: Card[] = [
      {
        id: "id-1",
        front: "Q1",
        back: "A1",
        tags: [],
        createdAt: "2026-04-01T00:00:00.000Z",
      },
    ];
    await saveCards(filePath, cards);

    const raw = await Bun.file(filePath).text();
    expect(raw).toBe(JSON.stringify(cards, null, 2));
  });
});

describe("round-trip persistence", () => {
  it("preserves all fields including optional reviewData", async () => {
    const filePath = tempPath();
    const cardWithReview: Card = {
      id: "id-r1",
      front: "Reviewed Q",
      back: "Reviewed A",
      tags: ["science", "biology"],
      createdAt: "2026-04-01T00:00:00.000Z",
      reviewData: {
        easeFactor: 2.36,
        interval: 10,
        repetitions: 3,
        nextReviewDate: "2026-04-14T00:00:00.000Z",
        lastReviewDate: "2026-04-04T00:00:00.000Z",
      },
    };
    const cardWithoutReview: Card = {
      id: "id-r2",
      front: "New Q",
      back: "New A",
      tags: [],
      createdAt: "2026-04-02T00:00:00.000Z",
    };

    const cards = [cardWithReview, cardWithoutReview];
    await saveCards(filePath, cards);
    const loaded = await loadCards(filePath);

    expect(loaded).toEqual(cards);
    expect(loaded[0].reviewData).toEqual(cardWithReview.reviewData);
    expect(loaded[1].reviewData).toBeUndefined();
  });
});

