import type { Card } from "./card";
import { calculateSm2, createDefaultSm2State } from "./sm2";

/** Quiz session state. */
export interface QuizSession {
	readonly cards: readonly Card[];
	currentIndex: number;
	readonly answers: Map<string, number>;
	updatedCards: Card[];
}

/**
 * Select cards that are due for review.
 *
 * Due cards (nextReviewDate <= now) are sorted by overdue-ness descending,
 * followed by new cards (no reviewData) in their original order.
 * Cards with a future nextReviewDate are excluded.
 *
 * @param cards - All available cards.
 * @param limit - Maximum number of cards to return (default 20).
 * @returns Cards selected for review.
 */
export function selectCardsForReview(cards: readonly Card[], limit = 20): Card[] {
	const now = Date.now();
	const dueCards: Card[] = [];
	const newCards: Card[] = [];

	for (const card of cards) {
		if (card.reviewData === undefined) {
			newCards.push(card);
		} else if (Date.parse(card.reviewData.nextReviewDate) <= now) {
			dueCards.push(card);
		}
		// else: future nextReviewDate — excluded
	}

	// Sort due cards by overdue-ness descending (most overdue first)
	dueCards.sort((a, b) => {
		const overdueA = now - Date.parse(a.reviewData!.nextReviewDate);
		const overdueB = now - Date.parse(b.reviewData!.nextReviewDate);
		return overdueB - overdueA;
	});

	return [...dueCards, ...newCards].slice(0, limit);
}

/** Start a new quiz session with the given cards. */
export function startQuiz(cards: Card[]): QuizSession {
	return {
		cards,
		currentIndex: 0,
		answers: new Map<string, number>(),
		updatedCards: [],
	};
}

/** Get the current card in the quiz, or undefined if done. */
export function currentCard(session: QuizSession): Card | undefined {
	return session.cards[session.currentIndex];
}

/** Record an answer with SM-2 quality and advance to the next card. */
export function answerCard(session: QuizSession, quality: number): void {
	const card = currentCard(session);
	if (!card) return;

	const state = card.reviewData === undefined
		? createDefaultSm2State()
		: { easeFactor: card.reviewData.easeFactor, interval: card.reviewData.interval, repetitions: card.reviewData.repetitions };

	const sm2Result = calculateSm2(state, quality);

	const updatedCard: Card = {
		...card,
		reviewData: {
			...sm2Result.state,
			nextReviewDate: sm2Result.nextReviewDate,
			lastReviewDate: new Date().toISOString(),
		},
	};

	session.answers.set(card.id, quality);
	session.updatedCards.push(updatedCard);
	session.currentIndex++;
}

/** Check if the quiz is complete. */
export function isQuizComplete(session: QuizSession): boolean {
	return session.currentIndex >= session.cards.length;
}

/** Score summary for a completed quiz session. */
export interface ScoreSummary {
	readonly total: number;
	readonly correct: number;
	readonly incorrect: number;
	readonly percentage: number;
}

/** Calculate score from a map of card ID -> SM-2 quality (0-5). */
export function calculateScore(answers: Map<string, number>): ScoreSummary {
	let correct = 0;
	let incorrect = 0;
	for (const [, quality] of answers) {
		if (quality >= 3) {
			correct++;
		} else {
			incorrect++;
		}
	}
	const total = correct + incorrect;
	const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
	return { total, correct, incorrect, percentage };
}

/** Format a score summary as a human-readable string. */
export function formatScore(summary: ScoreSummary): string {
	return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
}

