import { describe, expect, test } from "bun:test";
import { createCard } from "../src/card";
import type { Card } from "../src/card";
import { calculateScore } from "../src/score";
import { selectCardsForReview, startQuiz, answerCard } from "../src/quiz";

/** Helper: create an ISO date string offset from now by the given number of days. */
function daysFromNow(days: number): string {
	const d = new Date();
	d.setDate(d.getDate() + days);
	return d.toISOString();
}

/** Helper: create a card with reviewData that has a specific nextReviewDate. */
function dueCard(front: string, nextReviewDate: string): Card {
	return {
		...createCard(front, "back"),
		reviewData: {
			easeFactor: 2.5,
			interval: 1,
			repetitions: 1,
			nextReviewDate,
			lastReviewDate: null,
		},
	};
}

describe("selectCardsForReview", () => {
	test("returns due cards sorted by most overdue first", () => {
		const card2dAgo = dueCard("2d ago", daysFromNow(-2));
		const card5dAgo = dueCard("5d ago", daysFromNow(-5));
		const card1dAgo = dueCard("1d ago", daysFromNow(-1));

		const result = selectCardsForReview([card2dAgo, card5dAgo, card1dAgo]);

		expect(result[0].front).toBe("5d ago");
		expect(result[1].front).toBe("2d ago");
		expect(result[2].front).toBe("1d ago");
	});

	test("includes new cards (no reviewData) after due cards", () => {
		const dueA = dueCard("due-a", daysFromNow(-1));
		const dueB = dueCard("due-b", daysFromNow(-3));
		const newA = createCard("new-a", "back");
		const newB = createCard("new-b", "back");

		const result = selectCardsForReview([newA, dueA, newB, dueB]);

		// Due cards first (most overdue first)
		expect(result[0].front).toBe("due-b");
		expect(result[1].front).toBe("due-a");
		// Then new cards in original order
		expect(result[2].front).toBe("new-a");
		expect(result[3].front).toBe("new-b");
	});

	test("excludes cards with future nextReviewDate", () => {
		const futureCard = dueCard("future", daysFromNow(1));
		const dueNow = dueCard("due", daysFromNow(-1));

		const result = selectCardsForReview([futureCard, dueNow]);

		expect(result).toHaveLength(1);
		expect(result[0].front).toBe("due");
	});

	test("respects session limit (truncation)", () => {
		const cards = Array.from({ length: 5 }, (_, i) =>
			dueCard(`card-${i}`, daysFromNow(-i - 1)),
		);

		const result = selectCardsForReview(cards, 2);

		expect(result).toHaveLength(2);
	});

	test("returns empty array for empty input", () => {
		expect(selectCardsForReview([])).toEqual([]);
	});

	test("returns all cards when fewer than limit", () => {
		const cards = [
			dueCard("a", daysFromNow(-1)),
			dueCard("b", daysFromNow(-2)),
			createCard("c", "back"),
		];

		const result = selectCardsForReview(cards);

		expect(result).toHaveLength(3);
	});
});

describe("startQuiz", () => {
	test("initializes session with number-typed answers map and empty updatedCards", () => {
		const cards = [createCard("q", "a")];
		const session = startQuiz(cards);

		expect(session.answers).toBeInstanceOf(Map);
		expect(session.answers.size).toBe(0);
		expect(session.updatedCards).toEqual([]);
		expect(session.currentIndex).toBe(0);
	});
});

describe("answerCard", () => {
	test("stores quality rating in answers map", () => {
		const card = createCard("q", "a");
		const session = startQuiz([card]);

		answerCard(session, 4);

		expect(session.answers.get(card.id)).toBe(4);
	});

	test("updates card reviewData with SM-2 result", () => {
		const card = createCard("q", "a");
		const session = startQuiz([card]);

		answerCard(session, 4);

		const updated = session.updatedCards[0];
		expect(updated.reviewData).toBeDefined();
		expect(updated.reviewData!.interval).toBe(1);
		expect(updated.reviewData!.repetitions).toBe(1);
		expect(updated.reviewData!.easeFactor).toBeCloseTo(2.5, 5);
		expect(updated.reviewData!.nextReviewDate).toBeTruthy();
		expect(updated.reviewData!.lastReviewDate).toBeTruthy();
		// Verify it's a valid ISO date
		expect(() => new Date(updated.reviewData!.nextReviewDate)).not.toThrow();
		expect(() => new Date(updated.reviewData!.lastReviewDate!)).not.toThrow();
	});

	test("initializes default SM-2 state for new card (no reviewData)", () => {
		const card = createCard("q", "a");
		// card has no reviewData by default
		expect(card.reviewData).toBeUndefined();

		const session = startQuiz([card]);
		answerCard(session, 4);

		const updated = session.updatedCards[0];
		expect(updated.reviewData).toBeDefined();
		// Default state (EF 2.5, interval 0, reps 0) + quality 4 => interval 1, reps 1, EF ~2.5
		expect(updated.reviewData!.interval).toBe(1);
		expect(updated.reviewData!.repetitions).toBe(1);
		expect(updated.reviewData!.easeFactor).toBeCloseTo(2.5, 5);
	});

	test("accumulates multiple updated cards in updatedCards", () => {
		const cards = [
			createCard("q1", "a1"),
			createCard("q2", "a2"),
			createCard("q3", "a3"),
		];
		const session = startQuiz(cards);

		answerCard(session, 4);
		answerCard(session, 3);
		answerCard(session, 5);

		expect(session.updatedCards).toHaveLength(3);
	});

	test("advances currentIndex after each answer", () => {
		const cards = [createCard("q1", "a1"), createCard("q2", "a2")];
		const session = startQuiz(cards);

		expect(session.currentIndex).toBe(0);
		answerCard(session, 4);
		expect(session.currentIndex).toBe(1);
		answerCard(session, 3);
		expect(session.currentIndex).toBe(2);
	});
});

describe("Score integration", () => {
	test("quality >= 3 counts as correct", () => {
		const answers = new Map<string, number>([
			["a", 3],
			["b", 4],
			["c", 5],
		]);
		const score = calculateScore(answers);
		expect(score.correct).toBe(3);
		expect(score.incorrect).toBe(0);
	});

	test("quality < 3 counts as incorrect", () => {
		const answers = new Map<string, number>([
			["a", 0],
			["b", 1],
			["c", 2],
		]);
		const score = calculateScore(answers);
		expect(score.correct).toBe(0);
		expect(score.incorrect).toBe(3);
	});

	test("mixed qualities produce correct split", () => {
		const answers = new Map<string, number>([
			["a", 0],
			["b", 2],
			["c", 3],
			["d", 5],
		]);
		const score = calculateScore(answers);
		expect(score.correct).toBe(2);
		expect(score.incorrect).toBe(2);
	});
});

