 1→import type { Card } from "./card";
 2→import { calculateSm2, createDefaultSm2State } from "./sm2";
 3→
 4→/** Quiz session state. */
 5→export interface QuizSession {
 6→	readonly cards: readonly Card[];
 7→	currentIndex: number;
 8→	readonly answers: Map<string, number>;
 9→	updatedCards: Card[];
10→}
11→
12→/**
13→ * Select cards that are due for review.
14→ *
15→ * Due cards (nextReviewDate <= now) are sorted by overdue-ness descending,
16→ * followed by new cards (no reviewData) in their original order.
17→ * Cards with a future nextReviewDate are excluded.
18→ *
19→ * @param cards - All available cards.
20→ * @param limit - Maximum number of cards to return (default 20).
21→ * @returns Cards selected for review.
22→ */
23→export function selectCardsForReview(
24→	cards: readonly Card[],
25→	limit = 20,
26→): Card[] {
27→	const now = Date.now();
28→	const dueCards: Card[] = [];
29→	const newCards: Card[] = [];
30→
31→	for (const card of cards) {
32→		if (card.reviewData === undefined) {
33→			newCards.push(card);
34→		} else if (Date.parse(card.reviewData.nextReviewDate) <= now) {
35→			dueCards.push(card);
36→		}
37→		// else: future nextReviewDate — excluded
38→	}
39→
40→	// Sort due cards by overdue-ness descending (most overdue first)
41→	dueCards.sort((a, b) => {
42→		const overdueA = now - Date.parse(a.reviewData?.nextReviewDate);
43→		const overdueB = now - Date.parse(b.reviewData?.nextReviewDate);
44→		return overdueB - overdueA;
45→	});
46→
47→	return [...dueCards, ...newCards].slice(0, limit);
48→}
49→
50→/** Start a new quiz session with the given cards. */
51→export function startQuiz(cards: Card[]): QuizSession {
52→	return {
53→		cards,
54→		currentIndex: 0,
55→		answers: new Map<string, number>(),
56→		updatedCards: [],
57→	};
58→}
59→
60→/** Get the current card in the quiz, or undefined if done. */
61→export function currentCard(session: QuizSession): Card | undefined {
62→	return session.cards[session.currentIndex];
63→}
64→
65→/** Record an answer with SM-2 quality and advance to the next card. */
66→export function answerCard(session: QuizSession, quality: number): void {
67→	const card = currentCard(session);
68→	if (!card) return;
69→
70→	const state =
71→		card.reviewData === undefined
72→			? createDefaultSm2State()
73→			: {
74→					easeFactor: card.reviewData.easeFactor,
75→					interval: card.reviewData.interval,
76→					repetitions: card.reviewData.repetitions,
77→				};
78→
79→	const sm2Result = calculateSm2(state, quality);
80→
81→	const updatedCard: Card = {
82→		...card,
83→		reviewData: {
84→			...sm2Result.state,
85→			nextReviewDate: sm2Result.nextReviewDate,
86→			lastReviewDate: new Date().toISOString(),
87→		},
88→	};
89→
90→	session.answers.set(card.id, quality);
91→	session.updatedCards.push(updatedCard);
92→	session.currentIndex++;
93→}
94→
95→/** Check if the quiz is complete. */
96→export function isQuizComplete(session: QuizSession): boolean {
97→	return session.currentIndex >= session.cards.length;
98→}
99→

 1→/** Represents the current SM-2 state for a single card. */
 2→export interface Sm2State {
 3→	readonly easeFactor: number;
 4→	readonly interval: number;
 5→	readonly repetitions: number;
 6→}
 7→
 8→/** Result of an SM-2 calculation, containing the updated state and next review date. */
 9→export interface Sm2Result {
10→	readonly state: Sm2State;
11→	readonly nextReviewDate: string;
12→}
13→
14→/**
15→ * Creates the default initial SM-2 state for a new card.
16→ * @returns Default state with easeFactor 2.5, interval 0, repetitions 0.
17→ */
18→export function createDefaultSm2State(): Sm2State {
19→	return { easeFactor: 2.5, interval: 0, repetitions: 0 };
20→}
21→
22→/**
23→ * Implements the SM-2 spaced repetition algorithm.
24→ *
25→ * Given the current review state and a quality rating (0-5), calculates
26→ * the updated state (ease factor, interval, repetitions) and the next review date.
27→ *
28→ * @param state - Current SM-2 state for the card.
29→ * @param quality - Quality of recall, integer in [0, 5].
30→ * @returns The updated SM-2 state and next review date as ISO 8601 string.
31→ * @throws {Error} If quality is not an integer in [0, 5].
32→ */
33→export function calculateSm2(state: Sm2State, quality: number): Sm2Result {
34→	if (
35→		typeof quality !== "number" ||
36→		!Number.isInteger(quality) ||
37→		quality < 0 ||
38→		quality > 5
39→	) {
40→		throw new Error(
41→			`Invalid quality rating: ${quality}. Must be an integer between 0 and 5.`,
42→		);
43→	}
44→
45→	let newInterval: number;
46→	let newRepetitions: number;
47→
48→	if (quality >= 3) {
49→		if (state.repetitions === 0) {
50→			newInterval = 1;
51→		} else if (state.repetitions === 1) {
52→			newInterval = 6;
53→		} else {
54→			newInterval = Math.round(state.interval * state.easeFactor);
55→		}
56→		newRepetitions = state.repetitions + 1;
57→	} else {
58→		newInterval = 1;
59→		newRepetitions = 0;
60→	}
61→
62→	const newEF = Math.max(
63→		1.3,
64→		state.easeFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
65→	);
66→
67→	const now = new Date();
68→	now.setDate(now.getDate() + newInterval);
69→	const nextReviewDate = now.toISOString();
70→
71→	return {
72→		state: {
73→			easeFactor: newEF,
74→			interval: newInterval,
75→			repetitions: newRepetitions,
76→		},
77→		nextReviewDate,
78→	};
79→}
80→
81→/**
82→ * Maps a user-facing 1-4 rating to the SM-2 internal 0-5 quality scale.
83→ *
84→ * @param rating - User rating: 1 (Again), 2 (Hard), 3 (Good), 4 (Easy).
85→ * @returns SM-2 quality value: 1->0, 2->2, 3->4, 4->5.
86→ */
87→export function mapUserRating(rating: 1 | 2 | 3 | 4): 0 | 2 | 4 | 5 {
88→	const mapping: Record<1 | 2 | 3 | 4, 0 | 2 | 4 | 5> = {
89→		1: 0,
90→		2: 2,
91→		3: 4,
92→		4: 5,
93→	};
94→	return mapping[rating];
95→}
