 14→/** Helper: create a card with reviewData that has a specific nextReviewDate. */
 15→function dueCard(front: string, nextReviewDate: string): Card {
 16→	return {
 17→		...createCard(front, "back"),
 18→		reviewData: {
 19→			easeFactor: 2.5,
 20→			interval: 1,
