  7→/** Helper: create an ISO date string offset from now by the given number of days. */
  8→function daysFromNow(days: number): string {
  9→	const d = new Date();
 10→	d.setDate(d.getDate() + days);
 11→	return d.toISOString();
 12→}
 13→
 14→/** Helper: create a card with reviewData that has a specific nextReviewDate. */
 15→function dueCard(front: string, nextReviewDate: string): Card {
 16→	return {
 17→		...createCard(front, "back"),
 18→		reviewData: {
 19→			easeFactor: 2.5,
 20→			interval: 1,
 21→			repetitions: 1,
 22→			nextReviewDate,
 23→			lastReviewDate: null,
 24→		},
 25→	};
 26→}
 27→
 28→describe("selectCardsForReview", () => {
 29→	test("returns due cards sorted by most overdue first", () => {
 30→		const card2dAgo = dueCard("2d ago", daysFromNow(-2));
 31→		const card5dAgo = dueCard("5d ago", daysFromNow(-5));
 32→		const card1dAgo = dueCard("1d ago", daysFromNow(-1));
 33→
 34→		const result = selectCardsForReview([card2dAgo, card5dAgo, card1dAgo]);
 35→
 36→		expect(result[0].front).toBe("5d ago");
 37→		expect(result[1].front).toBe("2d ago");
 38→		expect(result[2].front).toBe("1d ago");
 39→	});
 40→
 41→	test("includes new cards (no reviewData) after due cards", () => {
 42→		const dueA = dueCard("due-a", daysFromNow(-1));
 43→		const dueB = dueCard("due-b", daysFromNow(-3));
 44→		const newA = createCard("new-a", "back");
 45→		const newB = createCard("new-b", "back");
 46→
 47→		const result = selectCardsForReview([newA, dueA, newB, dueB]);
 48→
 49→		// Due cards first (most overdue first)
 50→		expect(result[0].front).toBe("due-b");
 51→		expect(result[1].front).toBe("due-a");
 52→		// Then new cards in original order
 53→		expect(result[2].front).toBe("new-a");
 54→		expect(result[3].front).toBe("new-b");
 55→	});
 56→
 57→	test("excludes cards with future nextReviewDate", () => {
 58→		const futureCard = dueCard("future", daysFromNow(1));
 59→		const dueNow = dueCard("due", daysFromNow(-1));
 60→
 61→		const result = selectCardsForReview([futureCard, dueNow]);
 62→
 63→		expect(result).toHaveLength(1);
