 53→### Input Handling
 54→
 55→- Reads from stdin using Bun's `console` or `process.stdin`
 56→- Accepts single characters: `a`, `h`, `e` (case-insensitive)
 57→- On invalid input, re-prompts: `Invalid choice. Enter a, h, or e: `
 58→- Enter key reveals the answer (blocks until pressed)
 59→
 60→### Implementation Approach
 61→
 62→```ts
 63→/** Prompt the user for a line of input. */
 64→async function prompt(message: string): Promise<string> {
 65→  process.stdout.write(message);
 66→  for await (const line of console) {
 67→    return line.trim().toLowerCase();
 68→  }
 69→  return "";
 70→}
