126→function buildSessionSummary(session: QuizSession): SessionSummary {
127→  // Count grades from session.answers
128→  // Bucket next review dates from session.updatedCards
129→  // Group into: tomorrow, 2-7 days, 8-30 days, 30+ days
130→}
