133→## Main Function Flow
134→
135→```ts
136→async function main(): Promise<void> {
137→  const args = parseArgs(process.argv);
138→
139→  // 1. Load deck
140→  const deck = await loadDeck(args.deckPath);
141→  if (deck.length === 0) {
142→    console.log("No deck found. Create cards with 'add' command first.");
143→    return;
144→  }
145→
146→  // 2. Select cards for quiz
147→  const quizOptions: QuizOptions = {
148→    newCardLimit: args.newCardLimit,
149→    dueOnly: args.dueOnly,
150→    all: args.all,
151→  };
152→  const selectedCards = selectQuizCards(deck, quizOptions);
153→  if (selectedCards.length === 0) {
154→    console.log("No cards due for review. You're all caught up!");
155→    return;
156→  }
157→
158→  console.log(`Starting quiz with ${selectedCards.length} cards...\n`);
159→
160→  // 3. Run interactive quiz
161→  const session = startQuiz(selectedCards);
162→  while (!isQuizComplete(session)) {
163→    const rc = currentCard(session);
164→    if (!rc) break;
165→
166→    const cardNum = session.currentIndex + 1;
167→    const total = session.cards.length;
168→    console.log(`Card ${cardNum}/${total}\n`);
169→    console.log(`  Q: ${rc.card.front}\n`);
170→
171→    await prompt("  Press Enter to reveal answer...");
172→    console.log(`  A: ${rc.card.back}\n`);
173→
174→    const grade = await promptGrade();
175→    answerCard(session, grade);
176→    console.log("");
177→  }
178→
179→  // 4. Calculate and display summary
180→  const summary = buildSessionSummary(session);
181→  displaySummary(summary);
182→
183→  // 5. Persist updated cards to deck
184→  const updatedDeck = mergUpdatedCards(deck, session.updatedCards);
185→  await saveDeck(args.deckPath, updatedDeck);
186→  console.log(`Progress saved to ${args.deckPath}`);
187→}
188→```
189→
190→## Merging Updated Cards
191→
192→After a quiz session, only the reviewed cards have updated SM-2 state. These must be merged back into the full deck:
193→
194→```ts
195→/** Merge updated cards back into the full deck by card ID. */
196→function mergeUpdatedCards(
197→  deck: readonly ReviewCard[],
198→  updatedCards: readonly ReviewCard[]
199→): ReviewCard[] {
200→  const updatedMap = new Map(updatedCards.map(rc => [rc.card.id, rc]));
201→  return deck.map(rc => updatedMap.get(rc.card.id) ?? rc);
202→}
203→```
204→
205→## Edge Cases
206→
207→- **Ctrl+C during quiz**: Unreviewed cards retain their previous SM-2 state. Only cards already graded in the session are persisted (on next save). Since we save at the end, an interrupted session loses progress. This is acceptable for v1.
208→- **Empty input**: Re-prompt until valid grade is entered.
209→- **`--all` with `--due-only`**: `--all` takes precedence (show everything).
210→- **`--new-cards 0`**: Equivalent to `--due-only` (no new cards shown).
