 32→## Interactive Grading Prompt
 33→
 34→After revealing a card's answer, the user is prompted with three grading options:
 35→
 36→```
 37→Card 3/15
 38→
 39→  Q: What is the capital of France?
 40→
 41→  Press Enter to reveal answer...
 42→
 43→  A: Paris
 44→
 45→  Rate your recall:
 46→    (a) Again  - No recall / got it wrong
 47→    (h) Hard   - Recalled with difficulty
 48→    (e) Easy   - Perfect recall
 49→
 50→  Your grade: _
 51→```
 52→
 53→### Input Handling
 54→
 55→- Reads from stdin using Bun's `console` or `process.stdin`
 56→- Accepts single characters: `a`, `h`, `e` (case-insensitive)
 57→- On invalid input, re-prompts: `Invalid choice. Enter a, h, or e: `
 58→- Enter key reveals the answer (blocks until pressed)
 59→
 60→### Implementation Approach
 61→
 62→```ts
 63→/** Prompt the user for a line of input. */
 64→async function prompt(message: string): Promise<string> {
 65→  process.stdout.write(message);
 66→  for await (const line of console) {
 67→    return line.trim().toLowerCase();
 68→  }
 69→  return "";
 70→}
 71→
 72→/** Prompt for a grade, re-prompting on invalid input. */
 73→async function promptGrade(): Promise<Grade> {
 74→  while (true) {
 75→    const input = await prompt("  Your grade: ");
 76→    if (input === "a") return "again";
 77→    if (input === "h") return "hard";
 78→    if (input === "e") return "easy";
 79→    process.stdout.write("  Invalid choice. Enter a, h, or e: ");
 80→  }
 81→}
