/** SM-2 quality grade: integer 0-5 for compile-time safety. */
export type SM2Quality = 0 | 1 | 2 | 3 | 4 | 5;

/** SM-2 algorithm state tracked per card. */
export interface SM2State {
  readonly easinessFactor: number;
  readonly repetitions: number;
  readonly interval: number;
  readonly nextReviewDate: string;
}

/** Record of a single review event. */
export interface ReviewRecord {
  readonly quality: SM2Quality;
  readonly grade: Grade;
  readonly reviewedAt: string;
  readonly easinessFactor: number;
  readonly interval: number;
}

/** 4-point user-facing grade scale. */
export type Grade = "again" | "hard" | "good" | "easy";

export const INITIAL_EASINESS_FACTOR = 2.5;
export const MINIMUM_EASINESS_FACTOR = 1.3;

const GRADE_TO_QUALITY: Record<Grade, SM2Quality> = {
  again: 0,
  hard: 3,
  good: 4,
  easy: 5,
};

/** Get today's date as a YYYY-MM-DD string. */
export function todayDateString(): string {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function addDays(dateStr: string, days: number): string {
  const date = new Date(`${dateStr}T00:00:00`);
  date.setDate(date.getDate() + days);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Create the default SM-2 state for a new card. */
export function createInitialSM2State(today?: string): SM2State {
  return {
    easinessFactor: INITIAL_EASINESS_FACTOR,
    repetitions: 0,
    interval: 0,
    nextReviewDate: today ?? todayDateString(),
  };
}

/** Apply one review to an SM-2 state, returning the updated state. Pure function. */
export function calculateSM2(
  state: SM2State,
  quality: SM2Quality,
  today?: string,
): SM2State {
  if (!Number.isInteger(quality) || quality < 0 || quality > 5) {
    throw new RangeError(
      `Quality must be an integer between 0 and 5, got ${quality}`,
    );
  }

  const reviewDate = today ?? todayDateString();

  let newInterval: number;
  let newRepetitions: number;

  if (quality >= 3) {
    if (state.repetitions === 0) {
      newInterval = 1;
    } else if (state.repetitions === 1) {
      newInterval = 6;
    } else {
      newInterval = Math.round(state.interval * state.easinessFactor);
    }
    newInterval = Math.max(newInterval, 1);
    newRepetitions = state.repetitions + 1;
  } else {
    newInterval = 1;
    newRepetitions = 0;
  }

  const newEF = Math.max(
    state.easinessFactor +
      (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
    MINIMUM_EASINESS_FACTOR,
  );

  return {
    easinessFactor: newEF,
    repetitions: newRepetitions,
    interval: newInterval,
    nextReviewDate: addDays(reviewDate, newInterval),
  };
}

/** Map a user-facing grade to an SM-2 quality value (0-5). */
export function mapGradeToQuality(grade: Grade): SM2Quality {
  return GRADE_TO_QUALITY[grade];
}

/** Check if a card is due for review on or before the given date. */
export function isDue(state: SM2State, today?: string): boolean {
  const checkDate = today ?? todayDateString();
  return state.nextReviewDate <= checkDate;
}

/** Calculate how many days overdue a card is. Returns 0 if not overdue. */
export function getOverdueDays(state: SM2State, today?: string): number {
  const checkDate = today ?? todayDateString();
  if (state.nextReviewDate > checkDate) {
    return 0;
  }
  const dueDate = new Date(`${state.nextReviewDate}T00:00:00`);
  const nowDate = new Date(`${checkDate}T00:00:00`);
  const diffMs = nowDate.getTime() - dueDate.getTime();
  return Math.round(diffMs / (1000 * 60 * 60 * 24));
}

