import { describe, expect, test } from "bun:test";
import {
  type Grade,
  type SM2Quality,
  type SM2State,
  INITIAL_EASINESS_FACTOR,
  MINIMUM_EASINESS_FACTOR,
  calculateSM2,
  createInitialSM2State,
  getOverdueDays,
  isDue,
  mapGradeToQuality,
  todayDateString,
} from "../src/sm2";

describe("todayDateString", () => {
  test("returns YYYY-MM-DD format", () => {
    const result = todayDateString();
    expect(result).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });
});

describe("createInitialSM2State", () => {
  test("returns default values", () => {
    const state = createInitialSM2State("2026-01-15");
    expect(state.easinessFactor).toBe(2.5);
    expect(state.repetitions).toBe(0);
    expect(state.interval).toBe(0);
    expect(state.nextReviewDate).toBe("2026-01-15");
  });

  test("uses today when no date provided", () => {
    const state = createInitialSM2State();
    expect(state.nextReviewDate).toBe(todayDateString());
  });
});

describe("calculateSM2", () => {
  const initial: SM2State = {
    easinessFactor: 2.5,
    repetitions: 0,
    interval: 0,
    nextReviewDate: "2026-01-15",
  };

  describe("quality validation", () => {
    test("throws RangeError for quality < 0", () => {
      expect(() => calculateSM2(initial, -1 as SM2Quality)).toThrow(
        RangeError,
      );
    });

    test("throws RangeError for quality > 5", () => {
      expect(() => calculateSM2(initial, 6 as SM2Quality)).toThrow(
        RangeError,
      );
    });

    test("throws RangeError for non-integer quality", () => {
      expect(() => calculateSM2(initial, 3.5 as SM2Quality)).toThrow(
        RangeError,
      );
    });
  });

  describe("successful recall (quality >= 3)", () => {
    test("repetitions=0 produces interval=1", () => {
      const result = calculateSM2(initial, 4, "2026-01-15");
      expect(result.interval).toBe(1);
      expect(result.repetitions).toBe(1);
    });

    test("repetitions=1 produces interval=6", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitions: 1,
        interval: 1,
        nextReviewDate: "2026-01-16",
      };
      const result = calculateSM2(state, 4, "2026-01-16");
      expect(result.interval).toBe(6);
      expect(result.repetitions).toBe(2);
    });

    test("repetitions>=2 uses round(interval * currentEF)", () => {
      const state: SM2State = {
        easinessFactor: 2.7,
        repetitions: 2,
        interval: 6,
        nextReviewDate: "2026-01-22",
      };
      const result = calculateSM2(state, 5, "2026-01-22");
      expect(result.interval).toBe(Math.round(6 * 2.7)); // 16
    });
  });

  describe("failed recall (quality < 3)", () => {
    test("quality=0 resets repetitions and interval", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitions: 5,
        interval: 30,
        nextReviewDate: "2026-01-15",
      };
      const result = calculateSM2(state, 0, "2026-01-15");
      expect(result.repetitions).toBe(0);
      expect(result.interval).toBe(1);
    });

    test("quality=1 resets repetitions and interval", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitions: 3,
        interval: 15,
        nextReviewDate: "2026-01-15",
      };
      const result = calculateSM2(state, 1, "2026-01-15");
      expect(result.repetitions).toBe(0);
      expect(result.interval).toBe(1);
    });

    test("quality=2 resets repetitions and interval", () => {
      const state: SM2State = {
        easinessFactor: 2.5,
        repetitions: 3,
        interval: 15,
        nextReviewDate: "2026-01-15",
      };
      const result = calculateSM2(state, 2, "2026-01-15");
      expect(result.repetitions).toBe(0);
      expect(result.interval).toBe(1);
    });
  });

  describe("EF progression", () => {
    test("EF=2.5, quality=5 -> EF=2.6", () => {
      const result = calculateSM2(initial, 5, "2026-01-15");
      expect(result.easinessFactor).toBeCloseTo(2.6, 10);
    });

    test("EF=2.5, quality=3 -> EF=2.36", () => {
      const result = calculateSM2(initial, 3, "2026-01-15");
      expect(result.easinessFactor).toBeCloseTo(2.36, 10);
    });

    test("EF=2.5, quality=0 -> EF=1.7", () => {
      const result = calculateSM2(initial, 0, "2026-01-15");
      expect(result.easinessFactor).toBeCloseTo(1.7, 10);
    });

    test("EF=1.7, quality=0 -> clamped to 1.3", () => {
      const state: SM2State = {
        easinessFactor: 1.7,
        repetitions: 0,
        interval: 1,
        nextReviewDate: "2026-01-15",
      };
      const result = calculateSM2(state, 0, "2026-01-15");
      expect(result.easinessFactor).toBe(MINIMUM_EASINESS_FACTOR);
    });

    test("EF never drops below 1.3", () => {
      let state = createInitialSM2State("2026-01-15");
      for (let i = 0; i < 10; i++) {
        state = calculateSM2(state, 0, state.nextReviewDate);
        expect(state.easinessFactor).toBeGreaterThanOrEqual(
          MINIMUM_EASINESS_FACTOR,
        );
      }
    });
  });

  describe("interval progression (all Easy/q=5)", () => {
    test("follows expected progression: 1, 6, 16, 45", () => {
      let state = createInitialSM2State("2026-01-01");

      // 1st review: interval=1
      state = calculateSM2(state, 5, "2026-01-01");
