```ts
interface SessionSummary {
  readonly totalReviewed: number;
  readonly recalledCount: number;
  readonly incorrectCount: number;
  readonly percentage: number;
  readonly gradeCounts: Record<Grade, number>;
  readonly nextReviewBuckets: readonly ReviewBucket[];
}

interface ReviewBucket {
  readonly label: string;       // "tomorrow", "in 6 days", "in 15+ days"
  readonly count: number;
}
```

