content.content:
  1→# CLI Integration — Detailed Design
  2→
  3→## File: `src/index.ts` (modified)
  4→
  5→## New CLI Flags
  6→
  7→The `quiz` command gains these flags, parsed from `Bun.argv` (or `process.argv`):
  8→
  9→| Flag | Type | Default | Description |
 10→|------|------|---------|-------------|
 11→| `--due-only` | boolean | `false` | Only show cards that are due for review. No new cards. |
 12→| `--new-cards <n>` | number | `20` | Maximum number of new (never-reviewed) cards to include. |
 13→| `--all` | boolean | `false` | Show all cards regardless of schedule. Overrides other flags. |
 14→| `--deck <path>` | string | `"flashcards.json"` | Path to the deck JSON file. |
 15→| `--help` | boolean | `false` | Show usage information and exit. |
 16→
 17→Flag parsing will use simple `process.argv` iteration (no external library needed for this small set of flags).
 18→
 19→### `--help` Output
 20→
 21→```
 22→Usage: flashcard quiz [options]
 23→
 24→Options:
 25→  --due-only        Only show cards that are due for review
 26→  --new-cards <n>   Maximum number of new cards to include (default: 20)
 27→  --all             Show all cards regardless of schedule
 28→  --deck <path>     Path to the deck JSON file (default: flashcards.json)
 29→  --help            Show this help message
 30→
 31→During a quiz session:
 32→  1 = Again (no recall)    2 = Hard (difficult)
 33→  3 = Good (correct)       4 = Easy (perfect)
 34→  q = Quit and save progress
 35→```
 36→
 37→```ts
 38→interface CLIArgs {
 39→  readonly deckPath: string;
 40→  readonly dueOnly: boolean;
 41→  readonly newCardLimit: number;
 42→  readonly all: boolean;
 43→}
 44→
 45→function parseArgs(argv: string[]): CLIArgs {
 46→  // Parse --due-only, --new-cards <n>, --all, --deck <path>
 47→  // from process.argv (skip first two: bun, script path)
 48→}
 49→```
 50→
 51→## Interactive Grading Prompt
 52→
 53→After revealing a card's answer, the user is prompted with three grading options:
 54→
 55→```
 56→Card 3/15
 57→
 58→  Q: What is the capital of France?
 59→
 60→  Press Enter to reveal answer...
 61→
 62→  A: Paris
 63→
 64→  Rate your recall:
 65→    (1) Again  - No recall / got it wrong
 66→    (2) Hard   - Recalled with difficulty
 67→    (3) Good   - Correct with some hesitation
 68→    (4) Easy   - Perfect recall
 69→    (q) Quit   - Save progress and exit
 70→
 71→  Your grade: _
 72→```
 73→
 74→### Input Handling
 75→
 76→- Reads from stdin using Bun's `console` or `process.stdin`
 77→- Accepts single characters: `1`, `2`, `3`, `4` for grading, `q` to quit and save progress
 78→- On invalid input, re-prompts: `Invalid choice. Enter 1, 2, 3, 4, or q: `
 79→- Enter key reveals the answer (blocks until pressed)
 80→
 81→### Implementation Approach
 82→
 83→```ts
 84→/** Prompt the user for a line of input. */
 85→async function prompt(message: string): Promise<string> {
 86→  process.stdout.write(message);
 87→  for await (const line of console) {
 88→    return line.trim().toLowerCase();
 89→  }
 90→  return "";
 91→}
 92→
 93→/** Prompt for a grade, re-prompting on invalid input. Returns null if user quits. */
 94→async function promptGrade(): Promise<Grade | "quit"> {
 95→  while (true) {
 96→    const input = await prompt("  Your grade: ");
 97→    if (input === "1") return "again";
 98→    if (input === "2") return "hard";
 99→    if (input === "3") return "good";
100→    if (input === "4") return "easy";
101→    if (input === "q") return "quit";
102→    process.stdout.write("  Invalid choice. Enter 1, 2, 3, 4, or q: ");
103→  }
104→}
105→```
106→
107→## Session Summary Output
108→
109→After the quiz completes, a summary is displayed:
110→
111→```
112→── Session Complete ──────────────────────
113→
114→  Cards reviewed:  15
115→  Recalled:        12 (80%)
116→  Again:            3
117→  Hard:             2
118→  Good:             5
119→  Easy:             5
120→
121→  Next reviews:
122→    3 cards due tomorrow
123→    5 cards due in 6 days
124→    7 cards due in 15+ days
125→
126→──────────────────────────────────────────
127→```
128→
129→### Summary Data
130→
131→```ts
132→interface SessionSummary {
133→  readonly totalReviewed: number;
134→  readonly recalledCount: number;
135→  readonly incorrectCount: number;
136→  readonly percentage: number;
137→  readonly gradeCounts: Record<Grade, number>;
138→  readonly nextReviewBuckets: readonly ReviewBucket[];
139→}
140→
141→interface ReviewBucket {
142→  readonly label: string;       // "tomorrow", "in 6 days", "in 15+ days"
143→  readonly count: number;
144→}
145→```
146→
147→The summary is built from `session.updatedCards` after the quiz:
148→
149→```ts
150→function buildSessionSummary(session: QuizSession): SessionSummary {
151→  // Count grades from session.answers
152→  // Bucket next review dates from session.updatedCards
153→  // Group into: tomorrow, 2-7 days, 8-30 days, 30+ days
154→}
155→```
156→
157→## Main Function Flow
158→
159→```ts
160→async function main(): Promise<void> {
161→  const args = parseArgs(process.argv);
162→
163→  // 1. Load deck
164→  const deck = await loadDeck(args.deckPath);
165→  if (deck.length === 0) {
166→    console.log("No deck found. Create cards with 'add' command first.");
167→    return;
168→  }
169→
170→  // 2. Select cards for quiz
171→  const quizOptions: QuizOptions = {
172→    newCardLimit: args.newCardLimit,
173→    dueOnly: args.dueOnly,
174→    all: args.all,
175→  };
176→  const selectedCards = selectQuizCards(deck, quizOptions);
177→  if (selectedCards.length === 0) {
178→    console.log("No cards due for review. You're all caught up!");
179→    return;
180→  }
181→
182→  console.log(`Starting quiz with ${selectedCards.length} cards...\n`);
183→
184→  // 3. Run interactive quiz with graceful interrupt handling
185→  const session = startQuiz(selectedCards);
186→
187→  // Save partial progress helper (used by quit and SIGINT)
188→  async function saveProgress(): Promise<void> {
189→    if (session.updatedCards.length > 0) {
190→      const updatedDeck = mergeUpdatedCards(deck, session.updatedCards);
191→      await saveDeck(args.deckPath, updatedDeck);
192→      console.log(`\nPartial progress saved (${session.updatedCards.length} cards) to ${args.deckPath}`);
193→    } else {
194→      console.log("\nNo progress to save.");
195→    }
196→  }
197→
198→  // Flag-based SIGINT handling to avoid async race conditions.
199→  // Instead of calling async save inside the signal handler (which may not
200→  // complete before process.exit), we set a flag and let the main loop
201→  // detect it, then save and exit in the normal control flow.
202→  let shuttingDown = false;
203→  process.on("SIGINT", () => {
204→    console.log("\n\nInterrupted! Saving progress...");
205→    shuttingDown = true;
206→  });
207→
208→  let quitEarly = false;
209→  while (!isQuizComplete(session)) {
210→    if (shuttingDown) {
211→      quitEarly = true;
212→      break;
213→    }
214→
215→    const rc = currentCard(session);
216→    if (!rc) break;
217→
218→    const cardNum = session.currentIndex + 1;
219→    const total = session.cards.length;
220→    console.log(`Card ${cardNum}/${total}\n`);
221→    console.log(`  Q: ${rc.card.front}\n`);
222→
223→    await prompt("  Press Enter to reveal answer...");
224→    if (shuttingDown) {
225→      quitEarly = true;
226→      break;
227→    }
228→
229→    console.log(`  A: ${rc.card.back}\n`);
230→
231→    const grade = await promptGrade();
232→    if (shuttingDown || grade === "quit") {
233→      quitEarly = true;
234→      break;
235→    }
236→    answerCard(session, grade);
237→    console.log("");
238→  }
239→
240→  // 4. Calculate and display summary
241→  if (session.updatedCards.length > 0) {
242→    const summary = buildSessionSummary(session);
243→    displaySummary(summary);
244→    if (quitEarly) {
245→      console.log(`  (Session ended early — ${session.cards.length - session.currentIndex} cards skipped)\n`);
246→    }
247→  }
248→
249→  // 5. Persist updated cards to deck
250→  const updatedDeck = mergeUpdatedCards(deck, session.updatedCards);
251→  await saveDeck(args.deckPath, updatedDeck);
252→  console.log(`Progress saved to ${args.deckPath}`);
253→}
254→```
255→
256→## Merging Updated Cards
257→
258→After a quiz session, only the reviewed cards have updated SM-2 state. These must be merged back into the full deck:
259→
260→```ts
261→/** Merge updated cards back into the full deck by card ID. */
262→function mergeUpdatedCards(
263→  deck: readonly ReviewCard[],
264→  updatedCards: readonly ReviewCard[]
265→): ReviewCard[] {
266→  const updatedMap = new Map(updatedCards.map(rc => [rc.card.id, rc]));
267→  return deck.map(rc => updatedMap.get(rc.card.id) ?? rc);
268→}
269→```
270→
271→## Edge Cases
272→
273→- **Ctrl+C during quiz**: SIGINT handler sets a `shuttingDown` flag; the main quiz loop detects it, breaks out, and saves progress through the normal async flow. This avoids the race condition of calling async save inside a signal handler. Ungraded cards retain their previous SM-2 state.
274→- **Quit ('q') during quiz**: Saves progress for all graded cards, shows partial summary, and exits gracefully.
275→- **Empty input**: Re-prompt until valid grade is entered.
276→- **`--all` with `--due-only`**: `--all` takes precedence (show everything).
277→- **`--new-cards 0`**: Equivalent to `--due-only` (no new cards shown).
278→
279→## Testing Strategy
280→
281→CLI logic should be extracted into testable functions separate from I/O:
282→
283→**Unit-testable functions (no I/O):**
284→- `parseArgs`: test flag parsing with various argv combinations
285→- `mergeUpdatedCards`: test ID-based merging, no-op for empty updates
286→- `buildSessionSummary`: test grade counting, percentage calculation, review bucketing
287→
288→**Integration tests (with temp files):**
289→- Full session flow: load deck -> select cards -> simulate answers -> save -> verify file
290→- Partial quit: simulate quit after N cards -> verify only N cards saved
291→- SIGINT handler: verify partial progress is persisted
292→- `--help` flag: verify output and exit
293→- Empty deck / no due cards: verify correct messages
294→
295→**Approach for interactive prompts:**
296→- Extract `promptGrade` and `prompt` behind an interface so tests can inject mock I/O
297→- Alternatively, test the quiz loop logic separately from stdin/stdout
298→

  1→/** SM-2 quality grade: integer 0-5 for compile-time safety. */
  2→export type SM2Quality = 0 | 1 | 2 | 3 | 4 | 5;
  3→
  4→/** SM-2 algorithm state tracked per card. */
  5→export interface SM2State {
  6→	readonly easinessFactor: number;
  7→	readonly repetitions: number;
  8→	readonly interval: number;
  9→	readonly nextReviewDate: string;
 10→}
 11→
 12→/** Record of a single review event. */
 13→export interface ReviewRecord {
 14→	readonly quality: SM2Quality;
 15→	readonly grade: Grade;
 16→	readonly reviewedAt: string;
 17→	readonly easinessFactor: number;
 18→	readonly interval: number;
 19→}
 20→
 21→/** 4-point user-facing grade scale. */
 22→export type Grade = "again" | "hard" | "good" | "easy";
 23→
 24→export const INITIAL_EASINESS_FACTOR = 2.5;
 25→export const MINIMUM_EASINESS_FACTOR = 1.3;
 26→
 27→const GRADE_TO_QUALITY: Record<Grade, SM2Quality> = {
 28→	again: 0,
 29→	hard: 3,
 30→	good: 4,
 31→	easy: 5,
 32→};
 33→
 34→/** Get today's date as a YYYY-MM-DD string. */
 35→export function todayDateString(): string {
 36→	const d = new Date();
 37→	const year = d.getFullYear();
 38→	const month = String(d.getMonth() + 1).padStart(2, "0");
 39→	const day = String(d.getDate()).padStart(2, "0");
 40→	return `${year}-${month}-${day}`;
 41→}
 42→
 43→function addDays(dateStr: string, days: number): string {
 44→	const date = new Date(`${dateStr}T00:00:00`);
 45→	date.setDate(date.getDate() + days);
 46→	const year = date.getFullYear();
 47→	const month = String(date.getMonth() + 1).padStart(2, "0");
 48→	const day = String(date.getDate()).padStart(2, "0");
 49→	return `${year}-${month}-${day}`;
 50→}
 51→
 52→/** Create the default SM-2 state for a new card. */
 53→export function createInitialSM2State(today?: string): SM2State {
 54→	return {
 55→		easinessFactor: INITIAL_EASINESS_FACTOR,
 56→		repetitions: 0,
 57→		interval: 0,
 58→		nextReviewDate: today ?? todayDateString(),
 59→	};
 60→}
 61→
 62→/** Apply one review to an SM-2 state, returning the updated state. Pure function. */
 63→export function calculateSM2(
 64→	state: SM2State,
 65→	quality: SM2Quality,
 66→	today?: string,
 67→): SM2State {
 68→	if (!Number.isInteger(quality) || quality < 0 || quality > 5) {
 69→		throw new RangeError(
 70→			`Quality must be an integer between 0 and 5, got ${quality}`,
 71→		);
 72→	}
 73→
 74→	const reviewDate = today ?? todayDateString();
 75→
 76→	let newInterval: number;
 77→	let newRepetitions: number;
 78→
 79→	if (quality >= 3) {
 80→		if (state.repetitions === 0) {
 81→			newInterval = 1;
 82→		} else if (state.repetitions === 1) {
 83→			newInterval = 6;
 84→		} else {
 85→			newInterval = Math.round(state.interval * state.easinessFactor);
 86→		}
 87→		newInterval = Math.max(newInterval, 1);
 88→		newRepetitions = state.repetitions + 1;
 89→	} else {
 90→		newInterval = 1;
 91→		newRepetitions = 0;
 92→	}
 93→
 94→	const newEF = Math.max(
 95→		state.easinessFactor +
 96→			(0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)),
 97→		MINIMUM_EASINESS_FACTOR,
 98→	);
 99→
100→	return {
101→		easinessFactor: newEF,
102→		repetitions: newRepetitions,
103→		interval: newInterval,
104→		nextReviewDate: addDays(reviewDate, newInterval),
105→	};
106→}
107→
108→/** Map a user-facing grade to an SM-2 quality value (0-5). */
109→export function mapGradeToQuality(grade: Grade): SM2Quality {
110→	return GRADE_TO_QUALITY[grade];
111→}
112→
113→/** Check if a card is due for review on or before the given date. */
114→export function isDue(state: SM2State, today?: string): boolean {
115→	const checkDate = today ?? todayDateString();
116→	return state.nextReviewDate <= checkDate;
117→}
118→
119→/** Calculate how many days overdue a card is. Returns 0 if not overdue. */
120→export function getOverdueDays(state: SM2State, today?: string): number {
121→	const checkDate = today ?? todayDateString();
122→	if (state.nextReviewDate > checkDate) {
123→		return 0;
124→	}
125→	const dueDate = new Date(`${state.nextReviewDate}T00:00:00`);
126→	const nowDate = new Date(`${checkDate}T00:00:00`);
127→	const diffMs = nowDate.getTime() - dueDate.getTime();
128→	return Math.round(diffMs / (1000 * 60 * 60 * 24));
129→}
130→

 1→import type { Card } from "./card";
 2→
 3→/** Quiz session state. */
 4→export interface QuizSession {
 5→  readonly cards: readonly Card[];
 6→  currentIndex: number;
 7→  readonly answers: Map<string, boolean>;
 8→}
 9→
10→/** Start a new quiz session with the given cards. */
11→export function startQuiz(cards: Card[]): QuizSession {
12→  return {
13→    cards,
14→    currentIndex: 0,
15→    answers: new Map(),
16→  };
17→}
18→
19→/** Get the current card in the quiz, or undefined if done. */
20→export function currentCard(session: QuizSession): Card | undefined {
21→  return session.cards[session.currentIndex];
22→}
23→
24→/** Record an answer and advance to the next card. */
25→export function answerCard(session: QuizSession, correct: boolean): void {
26→  const card = currentCard(session);
27→  if (card) {
28→    session.answers.set(card.id, correct);
29→    session.currentIndex++;
30→  }
31→}
32→
33→/** Check if the quiz is complete. */
34→export function isQuizComplete(session: QuizSession): boolean {
35→  return session.currentIndex >= session.cards.length;
36→}
37→

 1→/** Score summary for a completed quiz session. */
 2→export interface ScoreSummary {
 3→  readonly total: number;
 4→  readonly correct: number;
 5→  readonly incorrect: number;
 6→  readonly percentage: number;
 7→}
 8→
 9→/** Calculate score from a map of card ID -> correct/incorrect. */
10→export function calculateScore(answers: Map<string, boolean>): ScoreSummary {
11→  let correct = 0;
12→  let incorrect = 0;
13→  for (const [, isCorrect] of answers) {
14→    if (isCorrect) {
15→      correct++;
16→    } else {
17→      incorrect++;
18→    }
19→  }
20→  const total = correct + incorrect;
21→  const percentage = total > 0 ? Math.round((correct / total) * 100) : 0;
22→  return { total, correct, incorrect, percentage };
23→}
24→
25→/** Format a score summary as a human-readable string. */
26→export function formatScore(summary: ScoreSummary): string {
27→  return `Score: ${summary.correct}/${summary.total} (${summary.percentage}%)`;
28→}
29→

 1→import { createCard } from "./card";
 2→import { answerCard, currentCard, isQuizComplete, startQuiz } from "./quiz";
 3→import { calculateScore, formatScore } from "./score";
 4→
 5→/** Main CLI entry point. */
 6→function main(): void {
 7→  console.log("Flashcard CLI v0.1.0");
 8→
 9→  // Demo: create some cards and run a quick quiz
10→  const cards = [
11→    createCard("What is TypeScript?", "A typed superset of JavaScript"),
12→    createCard("What is Bun?", "A fast JavaScript runtime"),
13→    createCard("What is SM-2?", "A spaced repetition algorithm"),
14→  ];
15→
16→  const session = startQuiz(cards);
17→
18→  // Simulate answering all cards correctly
19→  while (!isQuizComplete(session)) {
20→    const card = currentCard(session);
21→    if (card) {
22→      console.log(`Q: ${card.front}`);
23→      console.log(`A: ${card.back}`);
24→      answerCard(session, true);
25→    }
26→  }
27→
28→  const score = calculateScore(session.answers);
29→  console.log(formatScore(score));
30→}
31→
32→main();
33→

 1→/** Represents a single flashcard with a front (question) and back (answer). */
 2→export interface Card {
 3→  readonly id: string;
 4→  readonly front: string;
 5→  readonly back: string;
 6→  readonly tags: readonly string[];
 7→  readonly createdAt: string;
 8→}
 9→
10→/** Load cards from a JSON file. */
11→export function loadCards(filePath: string): Card[] {
12→  const raw = Bun.file(filePath);
13→  // In a real app we'd validate, but this is the initial skeleton
14→  return [] as Card[];
15→}
16→
17→/** Create a new card with a generated ID. */
18→export function createCard(front: string, back: string, tags: string[] = []): Card {
19→  return {
20→    id: crypto.randomUUID(),
21→    front,
22→    back,
23→    tags,
24→    createdAt: new Date().toISOString(),
25→  };
26→}
